{
  "name": "Elite Penalty Shootout",
  "description": "A high-fidelity penalty shootout simulator featuring dynamic difficulty adjustment, immersive visual feedback, and responsive drag-to-kick mechanics."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameState {
  IDLE = 'IDLE',
  DRAGGING = 'DRAGGING',
  KICKED = 'KICKED',
  RESULT = 'RESULT'
}

export interface Vec2 {
  x: number;
  y: number;
}

export interface GameMetrics {
  score: number;
  streak: number;
  bestStreak: number;
  attempts: number;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { Trophy, RefreshCcw, Settings, Zap, Target } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
// These variables act as the "Invisible Hand" to manipulate player experience
const BASE_GOAL_WIDTH_RATIO = 0.6; // Base percentage of the pitch width that is the goal
const MIN_GOAL_WIDTH_RATIO = 0.45; // Minimum size for high difficulty
const BASE_GK_SPEED = 0.05; // Goalkeeper interp speed
const MAX_GK_SPEED = 0.15; // Faster reaction at higher difficulty
const WIND_PULL_STRENGTH = 0.12; // How much "invisible wind" affects the ball path

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.3); // 0.0 to 1.0
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  // Refs for the Engine
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 }); // Normalized coordinates (0 to 1)
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); // Depth scale
  const gkPos = useRef<number>(0.5); // Goalkeeper X (0 to 1)
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);

  // --- DIFFICULTY CONTROLLER LOGIC ---
  // Calculates dynamic parameters based on the current platform_difficulty state
  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: difficulty * WIND_PULL_STRENGTH
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 150,
        spread: 70,
        origin: { y: 0.3 },
        colors: ['#22c55e', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 400);
    }
  };

  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.IDLE) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleDragMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleDragEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragEnd.current.x - dragStart.current.x) / window.innerWidth;
    const dy = (dragEnd.current.y - dragStart.current.y) / window.innerHeight;

    // Sensitivity & Constraints
    const speed = Math.sqrt(dx * dx + dy * dy);
    if (speed < 0.02) {
      setGameState(GameState.IDLE);
      return;
    }

    // Limit and scale velocity
    const kickPower = Math.min(speed * 1.5, 0.08);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();

      // Clear
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // --- DRAW FIELD ---
      const w = canvas.width;
      const h = canvas.height;

      // Pitch
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, '#064e3b');
      gradient.addColorStop(1, '#14532d');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      // Lines
      ctx.strokeStyle = 'rgba(255,255,255,0.2)';
      ctx.lineWidth = 4;
      ctx.strokeRect(50, 50, w - 100, h - 100);

      // Goal Post
      const goalX = w * (0.5 - goalWidth / 2);
      const goalW = w * goalWidth;
      const goalH = 120;
      const goalY = 80;

      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.moveTo(goalX, goalY + goalH);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalY + goalH);
      ctx.stroke();

      // Netting pattern
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i = 0; i <= 10; i++) {
        ctx.beginPath();
        ctx.moveTo(goalX + (goalW/10)*i, goalY);
        ctx.lineTo(goalX + (goalW/10)*i, goalY + goalH);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(goalX, goalY + (goalH/10)*i);
        ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i);
        ctx.stroke();
      }

      // --- PHYSICS ---
      if (gameState === GameState.KICKED) {
        // Move ball
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        // --- INVISIBLE HAND: WIND/PULL ---
        // Subtly push the ball off course based on difficulty
        const pullDir = Math.sin(frameRef.current * 0.05) > 0 ? 1 : -1;
        ballVel.current.x += pullDir * (windEffect * 0.001);

        // Scale ball (Depth Simulation)
        ballZ.current = Math.max(0.4, ballZ.current - 0.015);

        // --- GOALKEEPER AI ---
        // Reaction logic: The GK tracks the ball's X position
        // Higher difficulty increases the speed of interpolation (gkSpeed)
        const targetX = ballPos.current.x;
        const diffX = targetX - gkPos.current;
        gkPos.current += diffX * gkSpeed;
        gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));

        // --- COLLISION CHECKS ---
        const bX = ballPos.current.x * w;
        const bY = ballPos.current.y * h;

        // Goal Line check
        if (ballPos.current.y < 0.15) {
          const isWithinGoalX = ballPos.current.x > (0.5 - goalWidth / 2) && ballPos.current.x < (0.5 + goalWidth / 2);
          const isSave = Math.abs(ballPos.current.x - gkPos.current) < 0.08;

          if (isSave) {
            setLastResult('SAVE');
            setGameState(GameState.RESULT);
            setMetrics(prev => ({ ...prev, streak: 0 }));
            triggerJuice('SAVE', null as any);
          } else if (isWithinGoalX) {
            setLastResult('GOAL');
            setGameState(GameState.RESULT);
            setMetrics(prev => ({
              ...prev,
              score: prev.score + 1,
              streak: prev.streak + 1,
              bestStreak: Math.max(prev.bestStreak, prev.streak + 1)
            }));
            triggerJuice('GOAL');
          } else {
            setLastResult('MISS');
            setGameState(GameState.RESULT);
            setMetrics(prev => ({ ...prev, streak: 0 }));
          }
        }

        // Out of bounds
        if (ballPos.current.x < 0 || ballPos.current.x > 1 || ballPos.current.y < 0) {
           if (gameState === GameState.KICKED) {
              setLastResult('MISS');
              setGameState(GameState.RESULT);
              setMetrics(prev => ({ ...prev, streak: 0 }));
           }
        }
      } else if (gameState === GameState.IDLE || gameState === GameState.DRAGGING) {
        // Idle Goalkeeper breathing/shuffling
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.02) * 0.15;
      }

      // --- RENDER GK ---
      const gkScreenX = gkPos.current * w;
      const gkScreenY = goalY + goalH - 20;

      ctx.fillStyle = '#ef4444'; // Red jersey
      ctx.beginPath();
      ctx.roundRect(gkScreenX - 25, gkScreenY - 60, 50, 60, 8);
      ctx.fill();
      ctx.fillStyle = '#fde047'; // Head/Helmet
      ctx.beginPath();
      ctx.arc(gkScreenX, gkScreenY - 70, 15, 0, Math.PI * 2);
      ctx.fill();
      // Arms
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 10;
      ctx.lineCap = 'round';
      const armWave = Math.sin(frameRef.current * 0.1) * 10;
      ctx.beginPath();
      ctx.moveTo(gkScreenX - 25, gkScreenY - 50);
      ctx.lineTo(gkScreenX - 50, gkScreenY - 40 + armWave);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(gkScreenX + 25, gkScreenY - 50);
      ctx.lineTo(gkScreenX + 50, gkScreenY - 40 - armWave);
      ctx.stroke();

      // --- RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const ballSize = 25 * ballZ.current;

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath();
      ctx.ellipse(ballScreenX, ballScreenY + 5, ballSize, ballSize * 0.4, 0, 0, Math.PI * 2);
      ctx.fill();

      // Ball core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(ballScreenX, ballScreenY, ballSize, 0, Math.PI * 2);
      ctx.fill();

      // Details (Hexagons)
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1;
      for (let i = 0; i < 5; i++) {
        ctx.beginPath();
        const rot = frameRef.current * 0.1 + (i * Math.PI * 0.4);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * ballSize, ballScreenY + Math.sin(rot) * ballSize);
        ctx.stroke();
      }

      // --- RENDER DRAG LINE ---
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        ctx.setLineDash([5, 5]);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(ballScreenX, ballScreenY);
        // Invert vector for intuitive aiming
        const aimDx = (dragStart.current.x - dragEnd.current.x);
        const aimDy = (dragStart.current.y - dragEnd.current.y);
        ctx.lineTo(ballScreenX + aimDx, ballScreenY + aimDy);
        ctx.stroke();
        ctx.setLineDash([]);

        // Target indicator at end of drag line
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        ctx.beginPath();
        ctx.arc(ballScreenX + aimDx, ballScreenY + aimDy, 15, 0, Math.PI * 2);
        ctx.fill();
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    update();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(frameRef.current);
    };
  }, [gameState, getDifficultyParams]);

  return (
    <div className={`relative w-full h-screen select-none overflow-hidden ${isShaking ? 'shake' : ''}`}>
      <canvas
        ref={canvasRef}
        onMouseDown={handleDragStart}
        onMouseMove={handleDragMove}
        onMouseUp={handleDragEnd}
        onTouchStart={handleDragStart}
        onTouchMove={handleDragMove}
        onTouchEnd={handleDragEnd}
        className="w-full h-full cursor-crosshair"
      />

      {/* TOP OVERLAY: METRICS */}
      <div className="absolute top-6 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/40 backdrop-blur-md px-6 py-3 rounded-2xl border border-white/10">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">Score</span>
          <span className="text-2xl font-extrabold">{metrics.score}</span>
        </div>
        <div className="w-px h-8 bg-white/20" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-amber-400 uppercase tracking-widest">Streak</span>
          <div className="flex items-center gap-1">
            <Zap size={14} className="fill-amber-400 text-amber-400" />
            <span className="text-2xl font-extrabold">{metrics.streak}</span>
          </div>
        </div>
        <div className="w-px h-8 bg-white/20" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-purple-400 uppercase tracking-widest">Best</span>
          <span className="text-2xl font-extrabold">{metrics.bestStreak}</span>
        </div>
      </div>

      {/* RIGHT OVERLAY: DIFFICULTY CONTROL */}
      <div className="absolute right-6 top-1/2 -translate-y-1/2 bg-black/40 backdrop-blur-md p-4 rounded-3xl border border-white/10 flex flex-col items-center gap-4">
        <Settings size={20} className="text-white/50" />
        <div className="h-48 w-2 bg-white/10 rounded-full relative overflow-hidden group">
          <div 
            className="absolute bottom-0 w-full bg-gradient-to-t from-emerald-500 via-amber-500 to-red-500 transition-all duration-300" 
            style={{ height: `${difficulty * 100}%` }}
          />
          <input 
            type="range" 
            min="0" 
            max="1" 
            step="0.01" 
            value={difficulty}
            onChange={(e) => setDifficulty(parseFloat(e.target.value))}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            style={{ writingMode: 'vertical-lr', direction: 'rtl' }}
          />
        </div>
        <div className="flex flex-col items-center gap-1">
          <span className="text-[9px] font-bold uppercase text-white/40">Difficulty</span>
          <span className="text-sm font-bold">{(difficulty * 100).toFixed(0)}%</span>
        </div>
      </div>

      {/* FEEDBACK OVERLAY */}
      {lastResult && (
        <div className="absolute top-1/3 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center animate-bounce pointer-events-none">
          <h2 className={`text-7xl font-black italic uppercase tracking-tighter ${
            lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_20px_rgba(52,211,153,0.5)]' :
            lastResult === 'SAVE' ? 'text-red-400 drop-shadow-[0_0_20px_rgba(248,113,113,0.5)]' :
            'text-white/60'
          }`}>
            {lastResult}
          </h2>
          <p className="text-white/50 text-sm mt-2 font-semibold">TAP TO RESET</p>
        </div>
      )}

      {/* INSTRUCTIONS */}
      {gameState === GameState.IDLE && metrics.attempts === 0 && (
        <div className="absolute bottom-32 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 animate-pulse pointer-events-none">
          <div className="w-12 h-12 border-2 border-white/30 rounded-full flex items-center justify-center">
             <div className="w-2 h-2 bg-white rounded-full" />
          </div>
          <p className="text-white/60 font-bold uppercase tracking-widest text-xs">Swipe the ball to shoot</p>
        </div>
      )}

      {/* FOOTER ACTION */}
      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-4">
        {gameState === GameState.RESULT && (
          <button 
            onClick={resetBall}
            className="group flex items-center gap-2 bg-emerald-500 hover:bg-emerald-400 text-black px-8 py-4 rounded-2xl font-bold transition-all active:scale-95 shadow-[0_8px_0_rgb(5,150,105)] active:shadow-none active:translate-y-2"
          >
            <RefreshCcw size={20} className="group-hover:rotate-180 transition-transform duration-500" />
            NEXT SHOT
          </button>
        )}
      </div>

      {/* DIFFICULTY TOOLTIP (PLATFORM LOGIC DEMO) */}
      <div className="absolute bottom-6 right-6 text-right max-w-xs pointer-events-none hidden md:block">
        <h4 className="text-[10px] font-bold text-white/30 uppercase tracking-widest mb-1">Controller Logic</h4>
        <div className="space-y-1">
          <div className="flex justify-between items-center gap-4">
            <span className="text-[10px] text-white/20">GK Reaction</span>
            <div className="flex-1 h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-blue-400" style={{ width: `${(BASE_GK_SPEED + difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)) * 500}%` }} />
            </div>
          </div>
          <div className="flex justify-between items-center gap-4">
            <span className="text-[10px] text-white/20">Goal Size</span>
            <div className="flex-1 h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-emerald-400" style={{ width: `${(BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO))) * 150}%` }} />
            </div>
          </div>
          <div className="flex justify-between items-center gap-4">
            <span className="text-[10px] text-white/20">Wind Factor</span>
            <div className="flex-1 h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-amber-400" style={{ width: `${difficulty * 100}%` }} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { Trophy, RefreshCcw, Settings, Zap, Wind, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.4; 
const BASE_GK_SPEED = 0.06; 
const MAX_GK_SPEED = 0.18; 
const WIND_PULL_MAX = 0.15; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); // 0.0 to 1.0
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0);
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);

  // Initialize wind particles
  useEffect(() => {
    windParticles.current = Array.from({ length: 20 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  // --- ADAPTIVE DIFFICULTY LOGIC (THE INVISIBLE HAND) ---
  // The system subtly pushes or pulls based on the current platform_difficulty.
  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.01) * difficulty * WIND_PULL_MAX)
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 100,
        spread: 60,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    }
  };

  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.IDLE) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleDragMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleDragEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.02) {
      setGameState(GameState.IDLE);
      return;
    }

    const kickPower = Math.min(speed * 1.8, 0.1);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- DRAW ATMOSPHERE ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      // Grass Textures (Simple Stripes)
      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles Visualizer
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.1);
        if (p.x > 1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1;
        ctx.beginPath();
        ctx.moveTo(p.x * w, p.y * h);
        ctx.lineTo((p.x + 0.02) * w, p.y * h);
        ctx.stroke();
      });

      // Goal Rendering
      const goalX = w * (0.5 - goalWidth / 2);
      const goalW = w * goalWidth;
      const goalY = h * 0.15;
      const goalH = 150;

      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.strokeRect(goalX, goalY, goalW, goalH);

      // Net logic
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath();
        ctx.moveTo(goalX + (goalW/10)*i, goalY);
        ctx.lineTo(goalX + (goalW/10)*i, goalY + goalH);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(goalX, goalY + (goalH/10)*i);
        ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i);
        ctx.stroke();
      }

      // --- PHYSICS ---
      if (gameState === GameState.KICKED) {
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        // Dynamic "Invisible Hand" Wind Adjustment
        ballVel.current.x += windEffect * 0.002;
        ballZ.current = Math.max(0.35, ballZ.current - 0.018);

        // Goalkeeper AI (Reactive Tracking)
        const targetGKX = ballPos.current.x;
        const prevGKX = gkPos.current;
        gkPos.current += (targetGKX - gkPos.current) * gkSpeed;
        gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
        gkVelocity.current = gkPos.current - prevGKX;

        // Collision Logic
        if (ballPos.current.y < 0.22) {
          const isInGoalX = ballPos.current.x > (0.5 - goalWidth / 2) && ballPos.current.x < (0.5 + goalWidth / 2);
          const isGKSave = Math.abs(ballPos.current.x - gkPos.current) < 0.1;

          if (isGKSave) {
            setLastResult('SAVE');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.05)); // Adaptive easy
          } else if (isInGoalX) {
            setLastResult('GOAL');
            setGameState(GameState.RESULT);
            setMetrics(m => {
              const newStreak = m.streak + 1;
              return {
                ...m,
                score: m.score + 1,
                streak: newStreak,
                bestStreak: Math.max(m.bestStreak, newStreak)
              }
            });
            triggerJuice('GOAL');
            setDifficulty(d => Math.min(1.0, d + 0.08)); // Adaptive hard
          } else {
            setLastResult('MISS');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.03));
          }
        }
      } else {
        // Idle GK movement
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.15;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // Render GK
      const gkX = gkPos.current * w;
      const gkY = goalY + goalH - 10;
      const diveAngle = gkVelocity.current * 15;

      ctx.save();
      ctx.translate(gkX, gkY);
      ctx.rotate(diveAngle);
      // Body
      ctx.fillStyle = '#ef4444';
      ctx.fillRect(-20, -60, 40, 60);
      // Head
      ctx.fillStyle = '#fde047';
      ctx.beginPath();
      ctx.arc(0, -70, 12, 0, Math.PI * 2);
      ctx.fill();
      // Arms (spread)
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 12;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-20, -45); ctx.lineTo(-50, -65);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(20, -45); ctx.lineTo(50, -65);
      ctx.stroke();
      ctx.restore();

      // Render Ball
      const bX = ballPos.current.x * w;
      const bY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      ctx.shadowBlur = 10;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(bX, bY, bSize, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      // Ball Pattern (dynamic rotation simulation)
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = frameRef.current * 0.2 + (i * Math.PI * 2/3);
        ctx.moveTo(bX, bY);
        ctx.lineTo(bX + Math.cos(rot) * bSize, bY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // Drag Interface & Power Meter
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const dist = Math.sqrt(dX*dX + dY*dY);
        const pwr = Math.min(dist / 200, 1);

        // Power Arc
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#ef4444' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 4;
        ctx.arc(bX, bY, bSize + 10, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();

        // Aim Indicator
        ctx.setLineDash([5, 5]);
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath();
        ctx.moveTo(bX, bY);
        ctx.lineTo(bX + dX * 0.8, bY + dY * 0.8);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    update();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(frameRef.current);
    };
  }, [gameState, getDifficultyParams]);

  return (
    <div className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}>
      <canvas
        ref={canvasRef}
        onMouseDown={handleDragStart}
        onMouseMove={handleDragMove}
        onMouseUp={handleDragEnd}
        onTouchStart={handleDragStart}
        onTouchMove={handleDragMove}
        onTouchEnd={handleDragEnd}
        className="w-full h-full cursor-crosshair"
      />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-xl px-8 py-4 rounded-3xl border border-white/10 shadow-2xl">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest opacity-70">Goals</span>
          <span className="text-3xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-10 bg-white/10 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest opacity-70">On Fire</span>
          <div className="flex items-center gap-1">
            <Zap size={18} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
        <div className="w-px h-10 bg-white/10 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest opacity-70">Best</span>
          <span className="text-3xl font-black text-white">{metrics.bestStreak}</span>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
         <div className="flex items-center gap-2 bg-black/40 px-3 py-1.5 rounded-full border border-white/5 text-[10px] font-bold text-white/40 tracking-wider">
           <Activity size={12} />
           ADAPTIVE DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-48 h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div 
              className="h-full bg-gradient-to-r from-emerald-500 via-amber-500 to-red-500 transition-all duration-700" 
              style={{ width: `${difficulty * 100}%` }}
            />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
          <div className="animate-[scaleIn_0.3s_ease-out] flex flex-col items-center">
            <h2 className={`text-9xl font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_40px_rgba(52,211,153,0.6)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_40px_rgba(244,63,94,0.6)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-4 bg-white/10 backdrop-blur px-6 py-2 rounded-full border border-white/10 text-white font-bold text-sm tracking-widest uppercase">
              Tap to continue
            </div>
          </div>
        </div>
      )}

      {/* CONTROLS */}
      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6">
        {gameState === GameState.RESULT ? (
          <button 
            onClick={resetBall}
            className="group flex items-center gap-3 bg-white text-black px-10 py-5 rounded-2xl font-black text-lg transition-all active:scale-95 shadow-[0_10px_0_#d4d4d8] active:shadow-none active:translate-y-2"
          >
            <RefreshCcw size={22} className="group-hover:rotate-180 transition-transform duration-700" />
            RETRY KICK
          </button>
        ) : (
          <div className="flex flex-col items-center gap-2 opacity-50 animate-pulse">
            <Target size={32} className="text-white" />
            <p className="text-white font-black text-xs uppercase tracking-[0.2em]">Drag to Kick</p>
          </div>
        )}
      </div>

      {/* PLATFORM LOGIC OVERLAY (FOR DEMO) */}
      <div className="absolute bottom-6 right-6 bg-black/60 p-4 rounded-2xl border border-white/5 backdrop-blur hidden lg:block">
        <h3 className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-3">Platform Invisible Hand</h3>
        <div className="space-y-3">
          <div className="flex justify-between items-center gap-6">
            <span className="text-[11px] text-white/50">Goal Width</span>
            <span className="text-[11px] font-mono text-emerald-400">{(getDifficultyParams().goalWidth * 100).toFixed(1)}%</span>
          </div>
          <div className="flex justify-between items-center gap-6">
            <span className="text-[11px] text-white/50">GK Response</span>
            <span className="text-[11px] font-mono text-rose-400">{(getDifficultyParams().gkSpeed * 1000).toFixed(0)}ms</span>
          </div>
          <div className="flex justify-between items-center gap-6">
            <span className="text-[11px] text-white/50">Magnetic Pull</span>
            <span className="text-[11px] font-mono text-amber-400">{(Math.abs(getDifficultyParams().windEffect) * 100).toFixed(1)}%</span>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scaleIn {
          0% { transform: scale(0.5); opacity: 0; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.4; 
const BASE_GK_SPEED = 0.06; 
const MAX_GK_SPEED = 0.18; 
const WIND_PULL_MAX = 0.15; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0);
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);

  useEffect(() => {
    windParticles.current = Array.from({ length: 25 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.01) * difficulty * WIND_PULL_MAX)
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 100,
        spread: 70,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.015) {
      setGameState(GameState.IDLE);
      return;
    }

    const kickPower = Math.min(speed * 1.8, 0.12);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // Pitch Background
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      // Grass Stripes
      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.1);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath();
        ctx.moveTo(p.x * w, p.y * h);
        ctx.lineTo((p.x + 0.02) * w, p.y * h);
        ctx.stroke();
      });

      // Goal
      const goalX = w * (0.5 - goalWidth / 2);
      const goalW = w * goalWidth;
      const goalY = h * 0.15;
      const goalH = 150;

      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 8;
      ctx.strokeRect(goalX, goalY, goalW, goalH);

      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalY + goalH); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // Physics logic
      if (gameState === GameState.KICKED) {
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;
        ballVel.current.x += windEffect * 0.0025;
        ballZ.current = Math.max(0.35, ballZ.current - 0.018);

        // GK AI
        const targetGKX = ballPos.current.x;
        const prevGKX = gkPos.current;
        gkPos.current += (targetGKX - gkPos.current) * gkSpeed;
        gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
        gkVelocity.current = gkPos.current - prevGKX;

        // --- IMPROVED COLLISION & OUT OF BOUNDS ---
        const bX = ballPos.current.x;
        const bY = ballPos.current.y;

        // Check Goal Line
        if (bY < 0.22) {
          const isInGoalX = bX > (0.5 - goalWidth / 2) && bX < (0.5 + goalWidth / 2);
          const isGKSave = Math.abs(bX - gkPos.current) < 0.11;

          if (isGKSave) {
            setLastResult('SAVE');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.05));
          } else if (isInGoalX && bY > 0.12) {
            setLastResult('GOAL');
            setGameState(GameState.RESULT);
            setMetrics(m => {
              const newStreak = m.streak + 1;
              return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
            });
            triggerJuice('GOAL');
            setDifficulty(d => Math.min(1.0, d + 0.08));
          } else {
            // Missed (either high or wide)
            setLastResult('MISS');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.03));
          }
        } else if (bX < -0.1 || bX > 1.1 || bY > 1.1) {
          // Out of bounds sides or back
          setLastResult('MISS');
          setGameState(GameState.RESULT);
          setMetrics(m => ({ ...m, streak: 0 }));
        }
      } else {
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.15;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // Render GK
      ctx.save();
      ctx.translate(gkPos.current * w, goalY + goalH - 10);
      ctx.rotate(gkVelocity.current * 15);
      ctx.fillStyle = '#ef4444'; ctx.fillRect(-20, -60, 40, 60);
      ctx.fillStyle = '#fde047'; ctx.beginPath(); ctx.arc(0, -70, 12, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 12; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(-20, -45); ctx.lineTo(-50, -65); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(20, -45); ctx.lineTo(50, -65); ctx.stroke();
      ctx.restore();

      // Render Ball
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + 10, bSize, bSize * 0.4, 0, 0, Math.PI * 2); ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = frameRef.current * 0.15 + (i * Math.PI * 2/3);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * bSize, ballScreenY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // Drag Interface
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const pwr = Math.min(Math.sqrt(dX*dX + dY*dY) / 200, 1);
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#ef4444' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 6;
        ctx.arc(ballScreenX, ballScreenY, bSize + 12, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();
        ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); ctx.moveTo(ballScreenX, ballScreenY); ctx.lineTo(ballScreenX + dX * 0.7, ballScreenY + dY * 0.7); ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-xl px-8 py-4 rounded-3xl border border-white/10 shadow-2xl pointer-events-none">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest opacity-70">Goals</span>
          <span className="text-3xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-10 bg-white/10 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest opacity-70">Streak</span>
          <div className="flex items-center gap-1">
            <Zap size={18} className="fill-amber-400 text-amber-400" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
        <div className="w-px h-10 bg-white/10 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest opacity-70">Best</span>
          <span className="text-3xl font-black text-white">{metrics.bestStreak}</span>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none">
         <div className="flex items-center gap-2 bg-black/40 px-3 py-1.5 rounded-full border border-white/5 text-[10px] font-bold text-white/40 tracking-wider">
           <Activity size={12} />
           DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 to-rose-500 transition-all duration-700" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-none">
          <div className="animate-[scaleIn_0.3s_ease-out] flex flex-col items-center">
            <h2 className={`text-9xl font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_40px_rgba(52,211,153,0.6)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_40px_rgba(244,63,94,0.6)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-8 bg-white text-black px-8 py-3 rounded-full font-black text-sm tracking-[0.2em] uppercase animate-pulse">
              Click anywhere to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT */}
      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 pointer-events-none">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-2 opacity-50 animate-bounce">
            <Target size={32} className="text-white" />
            <p className="text-white font-black text-xs uppercase tracking-[0.2em]">Drag to Shoot</p>
          </div>
        )}
        {gameState === GameState.RESULT && (
           <button onClick={resetBall} className="pointer-events-auto group flex items-center gap-3 bg-white text-black px-10 py-5 rounded-2xl font-black text-lg transition-all active:scale-95 shadow-[0_10px_0_#d4d4d8] active:shadow-none active:translate-y-2">
            <RefreshCcw size={22} className="group-hover:rotate-180 transition-transform duration-700" />
            RETRY NOW
          </button>
        )}
      </div>

      {/* PLATFORM LOGIC OVERLAY */}
      <div className="absolute bottom-6 right-6 bg-black/60 p-4 rounded-2xl border border-white/5 backdrop-blur hidden lg:block pointer-events-none">
        <h3 className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-2">Platform Engine</h3>
        <div className="space-y-2">
          <div className="flex justify-between items-center gap-6"><span className="text-[10px] text-white/50">Goal Width</span><span className="text-[10px] font-mono text-emerald-400">{(getDifficultyParams().goalWidth * 100).toFixed(1)}%</span></div>
          <div className="flex justify-between items-center gap-6"><span className="text-[10px] text-white/50">GK Speed</span><span className="text-[10px] font-mono text-rose-400">{(getDifficultyParams().gkSpeed * 100).toFixed(1)}%</span></div>
          <div className="flex justify-between items-center gap-6"><span className="text-[10px] text-white/50">Wind Pull</span><span className="text-[10px] font-mono text-amber-400">{(Math.abs(getDifficultyParams().windEffect) * 100).toFixed(1)}%</span></div>
        </div>
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.5); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.4; 
const BASE_GK_SPEED = 0.06; 
const MAX_GK_SPEED = 0.18; 
const WIND_PULL_MAX = 0.15; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0);
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);

  useEffect(() => {
    windParticles.current = Array.from({ length: 25 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.01) * difficulty * WIND_PULL_MAX)
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 120,
        spread: 80,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.015) {
      setGameState(GameState.IDLE);
      return;
    }

    const kickPower = Math.min(speed * 2.0, 0.14);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- 1. PITCH BACKGROUND ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      // Grass Stripes
      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.1);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath(); ctx.moveTo(p.x * w, p.y * h); ctx.lineTo((p.x + 0.02) * w, p.y * h); ctx.stroke();
      });

      // Goal Positioning
      const goalX = w * (0.5 - goalWidth / 2);
      const goalW = w * goalWidth;
      const goalY = h * 0.15;
      const goalH = 150;

      // --- 2. GOAL NET (BACK LAYER) ---
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalY + goalH); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // --- 3. PHYSICS & LOGIC ---
      // We keep physics running even in RESULT state if it's a GOAL to allow the ball to enter the net
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.y > 0.11);

      if (isMoving) {
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        // Simulating wind during flight
        if (gameState === GameState.KICKED) {
          ballVel.current.x += windEffect * 0.0025;
          ballZ.current = Math.max(0.35, ballZ.current - 0.018);
        } else if (lastResult === 'GOAL') {
          // HIT THE NET: Rapidly decelerate and fall
          ballVel.current.x *= 0.8;
          ballVel.current.y *= 0.6;
          ballZ.current = Math.max(0.35, ballZ.current - 0.005);
        }

        // GK AI
        const targetGKX = ballPos.current.x;
        const prevGKX = gkPos.current;
        gkPos.current += (targetGKX - gkPos.current) * gkSpeed;
        gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
        gkVelocity.current = gkPos.current - prevGKX;

        // Collision logic (only trigger once while KICKED)
        if (gameState === GameState.KICKED && ballPos.current.y < 0.22) {
          const bX = ballPos.current.x;
          const isInGoalX = bX > (0.5 - goalWidth / 2) && bX < (0.5 + goalWidth / 2);
          const isGKSave = Math.abs(bX - gkPos.current) < 0.11;

          if (isGKSave) {
            setLastResult('SAVE');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.05));
          } else if (isInGoalX) {
            // GOAL! But we don't stop the ball here
            setLastResult('GOAL');
            setGameState(GameState.RESULT);
            setMetrics(m => {
              const newStreak = m.streak + 1;
              return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
            });
            triggerJuice('GOAL');
            setDifficulty(d => Math.min(1.0, d + 0.08));
          } else {
            setLastResult('MISS');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.03));
          }
        }
      } else if (gameState === GameState.IDLE) {
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.15;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // --- 4. RENDER GOALKEEPER ---
      ctx.save();
      ctx.translate(gkPos.current * w, goalY + goalH - 10);
      ctx.rotate(gkVelocity.current * 15);
      ctx.fillStyle = '#ef4444'; ctx.fillRect(-20, -60, 40, 60);
      ctx.fillStyle = '#fde047'; ctx.beginPath(); ctx.arc(0, -70, 12, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 12; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(-20, -45); ctx.lineTo(-50, -65); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(20, -45); ctx.lineTo(50, -65); ctx.stroke();
      ctx.restore();

      // --- 5. RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      // Ball Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + 10, bSize, bSize * 0.4, 0, 0, Math.PI * 2); ctx.fill();

      // Ball Core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = frameRef.current * 0.15 + (i * Math.PI * 2/3);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * bSize, ballScreenY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // --- 6. RENDER GOAL FRAME (FRONT LAYER) ---
      // This ensures the ball looks like it's INSIDE the net
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(goalX, goalY + goalH);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalY + goalH);
      ctx.stroke();

      // Drag Interface
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const pwr = Math.min(Math.sqrt(dX*dX + dY*dY) / 200, 1);
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#ef4444' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 6;
        ctx.arc(ballScreenX, ballScreenY, bSize + 12, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();
        ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.moveTo(ballScreenX, ballScreenY); ctx.lineTo(ballScreenX + dX * 0.8, ballScreenY + dY * 0.8); ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/70 backdrop-blur-xl px-10 py-5 rounded-[40px] border border-white/10 shadow-2xl pointer-events-none">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest opacity-80">Goals Scored</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-12 bg-white/20 mx-4" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest opacity-80">Hot Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={22} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/50 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/10 backdrop-blur-[1px] pointer-events-none">
          <div className="animate-[scaleIn_0.35s_cubic-bezier(.17,.67,.26,.99)] flex flex-col items-center">
            <h2 className={`text-[12rem] font-black italic uppercase tracking-tighter leading-none ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_60px_rgba(52,211,153,0.7)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_60px_rgba(244,63,94,0.7)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-4 bg-white/90 text-black px-10 py-3 rounded-full font-black text-sm tracking-[0.3em] uppercase shadow-2xl">
              Tap anywhere to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT / ACTION */}
      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 pointer-events-none">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-3 opacity-60 animate-bounce">
            <div className="w-12 h-12 border-2 border-white/40 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-xs uppercase tracking-[0.3em]">Flick the Ball</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.3); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-2px, 0, 0); } 20%, 80% { transform: translate3d(4px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-6px, 0, 0); } 40%, 60% { transform: translate3d(6px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.4; 
const BASE_GK_SPEED = 0.06; 
const MAX_GK_SPEED = 0.18; 
const WIND_PULL_MAX = 0.15; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0);
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);

  useEffect(() => {
    windParticles.current = Array.from({ length: 25 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.01) * difficulty * WIND_PULL_MAX)
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 150,
        spread: 90,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.012) {
      setGameState(GameState.IDLE);
      return;
    }

    const kickPower = Math.min(speed * 2.2, 0.15);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- 1. PITCH BACKGROUND ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      // Grass Stripes
      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.1);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath(); ctx.moveTo(p.x * w, p.y * h); ctx.lineTo((p.x + 0.015) * w, p.y * h); ctx.stroke();
      });

      // Goal Positioning
      const goalW = w * goalWidth;
      const goalX = w * (0.5 - goalWidth / 2);
      const goalY = h * 0.15; // Top bar height
      const goalH = 150;
      const goalBottom = goalY + goalH;

      // --- 2. GOAL NET (BACK LAYER) ---
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalBottom); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // --- 3. PHYSICS & LOGIC ---
      const isGoalProgress = gameState === GameState.RESULT && lastResult === 'GOAL';
      const isMoving = gameState === GameState.KICKED || isGoalProgress;

      if (isMoving) {
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        if (gameState === GameState.KICKED) {
          ballVel.current.x += windEffect * 0.002;
          ballZ.current = Math.max(0.35, ballZ.current - 0.02);
        } else if (isGoalProgress) {
          // HIT THE NET: Dramatic deceleration to stop "flying out"
          ballVel.current.x *= 0.75;
          ballVel.current.y *= 0.5;
          ballZ.current = Math.max(0.35, ballZ.current - 0.002);

          // Clamp ball to stay within the net back area
          if (ballPos.current.y < 0.13) {
             ballPos.current.y = 0.13;
             ballVel.current.y = 0;
          }
        }

        // GK AI tracking the ball
        if (gameState === GameState.KICKED) {
          const targetGKX = ballPos.current.x;
          gkPos.current += (targetGKX - gkPos.current) * gkSpeed;
          gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
          gkVelocity.current = (gkPos.current - (gkPos.current - (gkVelocity.current * 0.1))) * 0.5;
        }

        // Collision logic
        if (gameState === GameState.KICKED && ballPos.current.y < 0.22) {
          const bX = ballPos.current.x;
          const bY = ballPos.current.y;

          const withinPosts = bX > (0.5 - goalWidth / 2) && bX < (0.5 + goalWidth / 2);
          // Check if it's under the crossbar (crossbar is at goalY = 0.15)
          // We allow some buffer for visual depth, but anything < 0.15 is "over the bar"
          const underBar = bY > 0.15; 
          const isGKSave = Math.abs(bX - gkPos.current) < 0.11 && bY > 0.18;

          if (isGKSave) {
            setLastResult('SAVE');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.05));
          } else if (withinPosts && underBar) {
            setLastResult('GOAL');
            setGameState(GameState.RESULT);
            setMetrics(m => {
              const newStreak = m.streak + 1;
              return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
            });
            triggerJuice('GOAL');
            setDifficulty(d => Math.min(1.0, d + 0.06));
          } else {
            // Either wide of posts or over the crossbar
            setLastResult('MISS');
            setGameState(GameState.RESULT);
            setMetrics(m => ({ ...m, streak: 0 }));
            setDifficulty(d => Math.max(0.1, d - 0.03));
          }
        }

        // Final screen exit detection for MISS
        if (gameState === GameState.KICKED && (ballPos.current.y < 0.05 || Math.abs(ballPos.current.x - 0.5) > 0.6)) {
           setLastResult('MISS');
           setGameState(GameState.RESULT);
           setMetrics(m => ({ ...m, streak: 0 }));
        }
      } else if (gameState === GameState.IDLE) {
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.12;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // --- 4. RENDER GOALKEEPER ---
      ctx.save();
      ctx.translate(gkPos.current * w, goalBottom - 5);
      ctx.rotate(gkVelocity.current * 20);
      ctx.fillStyle = '#ef4444'; ctx.fillRect(-20, -60, 40, 60);
      ctx.fillStyle = '#fde047'; ctx.beginPath(); ctx.arc(0, -70, 12, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 12; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(-20, -45); ctx.lineTo(-50, -65); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(20, -45); ctx.lineTo(50, -65); ctx.stroke();
      ctx.restore();

      // --- 5. RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      // Ball Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + (bSize * 0.8), bSize, bSize * 0.3, 0, 0, Math.PI * 2); ctx.fill();

      // Ball Core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
      const rotation = isMoving ? frameRef.current * 0.2 : 0;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = rotation + (i * Math.PI * 2/3);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * bSize, ballScreenY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // --- 6. RENDER GOAL FRAME (FRONT LAYER) ---
      // This ensures the ball looks inside the goal if it's below the bar and between the posts
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(goalX, goalBottom);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalBottom);
      ctx.stroke();

      // Drag Interface
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const pwr = Math.min(Math.sqrt(dX*dX + dY*dY) / 180, 1);
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#f43f5e' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 6;
        ctx.arc(ballScreenX, ballScreenY, bSize + 12, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();

        ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.moveTo(ballScreenX, ballScreenY); ctx.lineTo(ballScreenX + dX * 0.75, ballScreenY + dY * 0.75); ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams, lastResult]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-12 py-6 rounded-[50px] border border-white/10 shadow-2xl pointer-events-none">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-14 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={24} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/60 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
          <div className="animate-[scaleIn_0.35s_cubic-bezier(.17,.67,.26,.99)] flex flex-col items-center">
            <h2 className={`text-[12rem] font-black italic uppercase tracking-tighter leading-none ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_60px_rgba(52,211,153,0.7)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_60px_rgba(244,63,94,0.7)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-6 bg-white/10 backdrop-blur-md text-white px-10 py-4 rounded-full font-black text-sm tracking-[0.4em] uppercase border border-white/20 shadow-2xl animate-pulse">
              Click to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT / ACTION */}
      <div className="absolute bottom-16 left-1/2 -translate-x-1/2 pointer-events-none">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-4 opacity-50 animate-bounce">
            <div className="w-14 h-14 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-4 h-4 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-xs uppercase tracking-[0.4em]">Swipe Up to Kick</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.3); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-2px, 0, 0); } 20%, 80% { transform: translate3d(4px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-6px, 0, 0); } 40%, 60% { transform: translate3d(6px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.4; 
const BASE_GK_SPEED = 0.06; 
const MAX_GK_SPEED = 0.18; 
const WIND_PULL_MAX = 0.15; 
const GOAL_LINE_Y = 0.23; // The logic line where we check for goal
const NET_DEPTH_Y = 0.14; // How deep the ball can go before hitting net

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0);
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);
  const hasCrossedLine = useRef(false); // Fix for tunneling

  useEffect(() => {
    windParticles.current = Array.from({ length: 25 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (difficulty * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.01) * difficulty * WIND_PULL_MAX)
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    hasCrossedLine.current = false;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 150,
        spread: 90,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.012) {
      setGameState(GameState.IDLE);
      return;
    }

    // Slightly reduced max power to keep visuals readable
    const kickPower = Math.min(speed * 2.0, 0.14);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- 1. PITCH BACKGROUND ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.1);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath(); ctx.moveTo(p.x * w, p.y * h); ctx.lineTo((p.x + 0.015) * w, p.y * h); ctx.stroke();
      });

      // Goal Positioning
      const goalW = w * goalWidth;
      const goalX = w * (0.5 - goalWidth / 2);
      const goalY = h * 0.15; 
      const goalH = 150;
      const goalBottom = goalY + goalH;

      // --- 2. GOAL NET (BACK LAYER) ---
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalBottom); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // --- 3. PHYSICS & LOGIC ---
      const isGoalProgress = gameState === GameState.RESULT && lastResult === 'GOAL';
      const isMoving = gameState === GameState.KICKED || isGoalProgress;

      if (isMoving) {
        // Physics integration
        const prevY = ballPos.current.y;
        const prevX = ballPos.current.x;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        if (gameState === GameState.KICKED) {
          ballVel.current.x += windEffect * 0.002;
          ballZ.current = Math.max(0.35, ballZ.current - 0.02);

          // GK AI
          const targetGKX = ballPos.current.x;
          gkPos.current += (targetGKX - gkPos.current) * gkSpeed;
          gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
          gkVelocity.current = (gkPos.current - (gkPos.current - (gkVelocity.current * 0.1))) * 0.5;

          // --- COLLISION DETECTION (Raycast/Tunneling Fix) ---
          if (!hasCrossedLine.current && ballPos.current.y <= GOAL_LINE_Y) {
            hasCrossedLine.current = true;

            // Calculate exact X where ball crossed GOAL_LINE_Y
            // We use interpolation to find precise impact point regardless of speed
            const fraction = (GOAL_LINE_Y - prevY) / (ballPos.current.y - prevY || -0.0001);
            const impactX = prevX + fraction * (ballPos.current.x - prevX);

            const withinPosts = impactX > (0.5 - goalWidth / 2) && impactX < (0.5 + goalWidth / 2);

            // GK Save Check
            const gkDist = Math.abs(impactX - gkPos.current);
            const isSave = gkDist < 0.12 && withinPosts; // Only save if within posts

            if (isSave) {
               setLastResult('SAVE');
               // Bounce off GK
               ballVel.current.y *= -0.5;
               ballVel.current.x += (Math.random() - 0.5) * 0.05;
               setDifficulty(d => Math.max(0.1, d - 0.05));
            } else if (withinPosts) {
               // GOAL - We accept any height as long as it's within X posts (Player satisfaction)
               setLastResult('GOAL');
               setMetrics(m => {
                  const newStreak = m.streak + 1;
                  return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
               });
               triggerJuice('GOAL');
               setDifficulty(d => Math.min(1.0, d + 0.06));
            } else {
               setLastResult('MISS');
               setMetrics(m => ({ ...m, streak: 0 }));
               setDifficulty(d => Math.max(0.1, d - 0.03));
            }
            setGameState(GameState.RESULT);
          }
        } 

        // --- NET PHYSICS (Post-Goal) ---
        if (isGoalProgress) {
          ballVel.current.x *= 0.92; // Friction
          ballVel.current.y *= 0.85; // Strong drag inside net

          // Clamp to Net Depth (Prevent flying out back)
          if (ballPos.current.y < NET_DEPTH_Y) {
             ballPos.current.y = NET_DEPTH_Y;
             ballVel.current.y *= -0.4; // Bounce off back net
          }
          // Clamp to side netting (optional, but good)
          const netLimit = goalWidth / 2 + 0.02;
          if (Math.abs(ballPos.current.x - 0.5) > netLimit) {
            ballVel.current.x *= -0.5;
            ballPos.current.x = ballPos.current.x > 0.5 ? 0.5 + netLimit : 0.5 - netLimit;
          }

          ballZ.current = Math.max(0.35, ballZ.current - 0.005);
        }

        // --- MISS BOUNDARY CHECK ---
        if (gameState === GameState.KICKED && (ballPos.current.y < 0.0 || Math.abs(ballPos.current.x - 0.5) > 0.6)) {
           if (!hasCrossedLine.current) {
               setLastResult('MISS');
               setGameState(GameState.RESULT);
               setMetrics(m => ({ ...m, streak: 0 }));
           }
        }

      } else if (gameState === GameState.IDLE) {
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.12;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // --- 4. RENDER GOALKEEPER ---
      ctx.save();
      ctx.translate(gkPos.current * w, goalBottom - 5);
      ctx.rotate(gkVelocity.current * 20);
      ctx.fillStyle = '#ef4444'; ctx.fillRect(-20, -60, 40, 60);
      ctx.fillStyle = '#fde047'; ctx.beginPath(); ctx.arc(0, -70, 12, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 12; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(-20, -45); ctx.lineTo(-50, -65); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(20, -45); ctx.lineTo(50, -65); ctx.stroke();
      ctx.restore();

      // --- 5. RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      // Ball Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + (bSize * 0.8), bSize, bSize * 0.3, 0, 0, Math.PI * 2); ctx.fill();

      // Ball Core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
      const rotation = isMoving ? frameRef.current * 0.2 : 0;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = rotation + (i * Math.PI * 2/3);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * bSize, ballScreenY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // --- 6. RENDER GOAL FRAME (FRONT LAYER) ---
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(goalX, goalBottom);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalBottom);
      ctx.stroke();

      // Drag Interface
      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const pwr = Math.min(Math.sqrt(dX*dX + dY*dY) / 180, 1);
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#f43f5e' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 6;
        ctx.arc(ballScreenX, ballScreenY, bSize + 12, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();

        ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.moveTo(ballScreenX, ballScreenY); ctx.lineTo(ballScreenX + dX * 0.75, ballScreenY + dY * 0.75); ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams, lastResult]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-12 py-6 rounded-[50px] border border-white/10 shadow-2xl pointer-events-none">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-14 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={24} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/60 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
          <div className="animate-[scaleIn_0.35s_cubic-bezier(.17,.67,.26,.99)] flex flex-col items-center">
            <h2 className={`text-[12rem] font-black italic uppercase tracking-tighter leading-none ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_60px_rgba(52,211,153,0.7)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_60px_rgba(244,63,94,0.7)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-6 bg-white/10 backdrop-blur-md text-white px-10 py-4 rounded-full font-black text-sm tracking-[0.4em] uppercase border border-white/20 shadow-2xl animate-pulse">
              Click to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT / ACTION */}
      <div className="absolute bottom-16 left-1/2 -translate-x-1/2 pointer-events-none">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-4 opacity-50 animate-bounce">
            <div className="w-14 h-14 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-4 h-4 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-xs uppercase tracking-[0.4em]">Swipe Up to Kick</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.3); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-2px, 0, 0); } 20%, 80% { transform: translate3d(4px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-6px, 0, 0); } 40%, 60% { transform: translate3d(6px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.38; // Slightly narrower max difficulty
const BASE_GK_SPEED = 0.05; 
const MAX_GK_SPEED = 0.22; // Faster max speed
const WIND_PULL_MAX = 0.18; 
const GOAL_LINE_Y = 0.23; 
const NET_DEPTH_Y = 0.14; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0); // Used for tilt calculation
  const dragStart = useRef<Vec2 | null>(null);
  const dragEnd = useRef<Vec2 | null>(null);
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);
  const hasCrossedLine = useRef(false);

  useEffect(() => {
    windParticles.current = Array.from({ length: 30 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    // Non-linear scaling: starts easy, gets hard fast
    const easeDiff = difficulty < 0.5 ? 2 * difficulty * difficulty : 1 - Math.pow(-2 * difficulty + 2, 2) / 2;

    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (easeDiff * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.015) * difficulty * WIND_PULL_MAX),
      // Prediction Mix: 0 = Chase Ball, 1 = Go to where ball will be
      predictionMix: Math.min(0.95, difficulty * 1.2) 
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    hasCrossedLine.current = false;
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 150,
        spread: 90,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    } else if (type === 'SAVE') {
      // Sparks for save
      confetti({
        particleCount: 50,
        spread: 40,
        startVelocity: 20,
        origin: { x: gkPos.current, y: 0.25 },
        colors: ['#f43f5e', '#ffffff'],
        disableForReducedMotion: true,
        ticks: 50
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 150);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x: clientX, y: clientY };
    dragEnd.current = { x: clientX, y: clientY };
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragEnd.current = { x: clientX, y: clientY };
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || !dragStart.current || !dragEnd.current) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const dx = (dragStart.current.x - dragEnd.current.x) / window.innerWidth;
    const dy = (dragStart.current.y - dragEnd.current.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.012) {
      setGameState(GameState.IDLE);
      return;
    }

    const kickPower = Math.min(speed * 2.1, 0.145);
    const angle = Math.atan2(dy, dx);

    ballVel.current = {
      x: Math.cos(angle) * kickPower,
      y: Math.sin(angle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect, predictionMix } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- 1. PITCH BACKGROUND ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles
      ctx.strokeStyle = `rgba(255,255,255,${0.05 + difficulty * 0.1})`;
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.15);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath(); ctx.moveTo(p.x * w, p.y * h); ctx.lineTo((p.x + 0.02 + Math.abs(windEffect) * 0.1) * w, p.y * h); ctx.stroke();
      });

      // Goal Params
      const goalW = w * goalWidth;
      const goalX = w * (0.5 - goalWidth / 2);
      const goalY = h * 0.15; 
      const goalH = 150;
      const goalBottom = goalY + goalH;

      // --- 2. GOAL NET ---
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalBottom); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // --- 3. PHYSICS & LOGIC ---
      const isGoalProgress = gameState === GameState.RESULT && lastResult === 'GOAL';
      const isMoving = gameState === GameState.KICKED || isGoalProgress;

      if (isMoving) {
        const prevY = ballPos.current.y;
        const prevX = ballPos.current.x;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        if (gameState === GameState.KICKED) {
          ballVel.current.x += windEffect * 0.0025;
          ballZ.current = Math.max(0.35, ballZ.current - 0.02);

          // --- IMPROVED GK AI (PREDICTION) ---
          let targetX = ballPos.current.x;
          // If ball is moving up (towards goal), predict its X intersection
          if (ballVel.current.y < 0) {
             const distY = ballPos.current.y - GOAL_LINE_Y;
             const steps = distY / Math.abs(ballVel.current.y);
             const predictedX = ballPos.current.x + (ballVel.current.x * steps);

             // Mix current position and predicted position based on difficulty
             // Low difficulty = chase ball (late)
             // High difficulty = move to intercept (smart)
             targetX = ballPos.current.x * (1 - predictionMix) + predictedX * predictionMix;
          }

          // Smoothly move GK
          const dx = targetX - gkPos.current;
          gkPos.current += dx * gkSpeed;
          gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));

          // Calculate lean/velocity for visuals
          gkVelocity.current = (gkPos.current - (gkPos.current - dx * gkSpeed)) * 2; // Amplify for visual effect

          // --- COLLISION ---
          if (!hasCrossedLine.current && ballPos.current.y <= GOAL_LINE_Y) {
            hasCrossedLine.current = true;

            const fraction = (GOAL_LINE_Y - prevY) / (ballPos.current.y - prevY || -0.0001);
            const impactX = prevX + fraction * (ballPos.current.x - prevX);

            const withinPosts = impactX > (0.5 - goalWidth / 2) && impactX < (0.5 + goalWidth / 2);

            // GK Reach is wider than just body
            const gkReach = 0.13; 
            const gkDist = Math.abs(impactX - gkPos.current);
            const isSave = gkDist < gkReach && withinPosts;

            if (isSave) {
               setLastResult('SAVE');
               ballVel.current.y *= -0.5;
               ballVel.current.x += (Math.random() - 0.5) * 0.1;
               setDifficulty(d => Math.max(0.1, d - 0.05));
               triggerJuice('SAVE');
            } else if (withinPosts) {
               setLastResult('GOAL');
               setMetrics(m => {
                  const newStreak = m.streak + 1;
                  return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
               });
               triggerJuice('GOAL');
               setDifficulty(d => Math.min(1.0, d + 0.08));
            } else {
               setLastResult('MISS');
               setMetrics(m => ({ ...m, streak: 0 }));
               setDifficulty(d => Math.max(0.1, d - 0.03));
            }
            setGameState(GameState.RESULT);
          }
        } 

        if (isGoalProgress) {
          ballVel.current.x *= 0.92;
          ballVel.current.y *= 0.85;
          if (ballPos.current.y < NET_DEPTH_Y) {
             ballPos.current.y = NET_DEPTH_Y;
             ballVel.current.y *= -0.4;
          }
          const netLimit = goalWidth / 2 + 0.02;
          if (Math.abs(ballPos.current.x - 0.5) > netLimit) {
            ballVel.current.x *= -0.5;
            ballPos.current.x = ballPos.current.x > 0.5 ? 0.5 + netLimit : 0.5 - netLimit;
          }
          ballZ.current = Math.max(0.35, ballZ.current - 0.005);
        }

        if (gameState === GameState.KICKED && (ballPos.current.y < 0.0 || Math.abs(ballPos.current.x - 0.5) > 0.6)) {
           if (!hasCrossedLine.current) {
               setLastResult('MISS');
               setGameState(GameState.RESULT);
               setMetrics(m => ({ ...m, streak: 0 }));
           }
        }

      } else if (gameState === GameState.IDLE) {
        // Idle animation
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.08;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // --- 4. RENDER GOALKEEPER (NEW VISUALS) ---
      const gkX = gkPos.current * w;
      const gkY = goalBottom - 5;

      ctx.save();
      ctx.translate(gkX, gkY);

      // Calculate Dive Angle based on velocity
      // If moving fast right, lean right (rotate clockwise)
      let leanAngle = gkVelocity.current * 25; 
      // Clamp lean
      leanAngle = Math.max(-1.2, Math.min(1.2, leanAngle));

      ctx.rotate(leanAngle);

      // Body (Jersey)
      ctx.fillStyle = '#ef4444'; 
      // Tapered body for better look
      ctx.beginPath();
      ctx.moveTo(-18, -55);
      ctx.lineTo(18, -55);
      ctx.lineTo(14, 0);
      ctx.lineTo(-14, 0);
      ctx.fill();

      // Head
      ctx.fillStyle = '#fde047'; 
      ctx.beginPath(); 
      ctx.arc(0, -65, 12, 0, Math.PI * 2); 
      ctx.fill();

      // Arms (Dynamic Reaching)
      ctx.strokeStyle = '#ef4444'; 
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // If ball is active, reach towards it relative to GK center
      let leftArmAngle = Math.PI - 0.5;
      let rightArmAngle = 0.5;

      if (isMoving && ballPos.current.y < 0.6) {
        // Simple IK-like aiming
        const relX = ballPos.current.x - gkPos.current;
        if (relX < 0) { // Ball on left
             leftArmAngle = Math.PI + 0.2; // Reach up/out
             rightArmAngle = Math.PI / 2; // Balance
        } else { // Ball on right
             rightArmAngle = -0.2; // Reach up/out
             leftArmAngle = Math.PI / 2; // Balance
        }
      }

      // Left Arm
      ctx.beginPath();
      ctx.moveTo(-16, -50);
      ctx.lineTo(-16 + Math.cos(leftArmAngle) * 35, -50 - Math.sin(leftArmAngle) * 35);
      ctx.stroke();

      // Right Arm
      ctx.beginPath();
      ctx.moveTo(16, -50);
      ctx.lineTo(16 + Math.cos(rightArmAngle) * 35, -50 - Math.sin(rightArmAngle) * 35);
      ctx.stroke();

      // Gloves
      ctx.fillStyle = '#fde047';
      ctx.beginPath(); ctx.arc(-16 + Math.cos(leftArmAngle) * 35, -50 - Math.sin(leftArmAngle) * 35, 8, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(16 + Math.cos(rightArmAngle) * 35, -50 - Math.sin(rightArmAngle) * 35, 8, 0, Math.PI*2); ctx.fill();

      ctx.restore();

      // --- 5. RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + (bSize * 0.8), bSize, bSize * 0.3, 0, 0, Math.PI * 2); ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
      const rotation = isMoving ? frameRef.current * 0.2 : 0;
      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = rotation + (i * Math.PI * 2/3);
        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + Math.cos(rot) * bSize, ballScreenY + Math.sin(rot) * bSize);
        ctx.stroke();
      }

      // --- 6. FRONT POSTS ---
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(goalX, goalBottom);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalBottom);
      ctx.stroke();

      if (gameState === GameState.DRAGGING && dragStart.current && dragEnd.current) {
        const dX = dragStart.current.x - dragEnd.current.x;
        const dY = dragStart.current.y - dragEnd.current.y;
        const pwr = Math.min(Math.sqrt(dX*dX + dY*dY) / 180, 1);
        ctx.beginPath();
        ctx.strokeStyle = pwr > 0.8 ? '#f43f5e' : pwr > 0.4 ? '#fbbf24' : '#10b981';
        ctx.lineWidth = 6;
        ctx.arc(ballScreenX, ballScreenY, bSize + 12, -Math.PI/2, -Math.PI/2 + (pwr * Math.PI * 2));
        ctx.stroke();

        ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.moveTo(ballScreenX, ballScreenY); ctx.lineTo(ballScreenX + dX * 0.75, ballScreenY + dY * 0.75); ctx.stroke();
        ctx.setLineDash([]);
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams, lastResult]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-12 py-6 rounded-[50px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-14 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={24} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/60 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
          <div className="animate-[scaleIn_0.35s_cubic-bezier(.17,.67,.26,.99)] flex flex-col items-center">
            <h2 className={`text-[12rem] font-black italic uppercase tracking-tighter leading-none ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_60px_rgba(52,211,153,0.7)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_60px_rgba(244,63,94,0.7)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-6 bg-white/10 backdrop-blur-md text-white px-10 py-4 rounded-full font-black text-sm tracking-[0.4em] uppercase border border-white/20 shadow-2xl animate-pulse">
              Click to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT / ACTION */}
      <div className="absolute bottom-16 left-1/2 -translate-x-1/2 pointer-events-none z-10">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-4 opacity-50 animate-bounce">
            <div className="w-14 h-14 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-4 h-4 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-xs uppercase tracking-[0.4em]">Swipe Up to Kick</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.3); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-2px, 0, 0); } 20%, 80% { transform: translate3d(4px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-6px, 0, 0); } 40%, 60% { transform: translate3d(6px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- PLATFORM DIFFICULTY CONSTANTS ---
const BASE_GOAL_WIDTH_RATIO = 0.55; 
const MIN_GOAL_WIDTH_RATIO = 0.38; 
const BASE_GK_SPEED = 0.05; 
const MAX_GK_SPEED = 0.22; 
const WIND_PULL_MAX = 0.18; 
const GOAL_LINE_Y = 0.23; 
const NET_DEPTH_Y = 0.14; 

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballPos = useRef<Vec2>({ x: 0.5, y: 0.85 });
  const ballVel = useRef<Vec2>({ x: 0, y: 0 });
  const ballZ = useRef<number>(1); 
  const ballCurve = useRef<number>(0); // New: Curve factor

  const gkPos = useRef<number>(0.5);
  const gkVelocity = useRef<number>(0); 

  // Drag handling
  const dragPath = useRef<Vec2[]>([]); // New: Store full path for curve detection
  const frameRef = useRef<number>(0);
  const windParticles = useRef<{x: number, y: number, s: number}[]>([]);
  const hasCrossedLine = useRef(false);

  useEffect(() => {
    windParticles.current = Array.from({ length: 30 }, () => ({
      x: Math.random(),
      y: Math.random(),
      s: 0.002 + Math.random() * 0.005
    }));
  }, []);

  const getDifficultyParams = useCallback(() => {
    const easeDiff = difficulty < 0.5 ? 2 * difficulty * difficulty : 1 - Math.pow(-2 * difficulty + 2, 2) / 2;

    return {
      goalWidth: BASE_GOAL_WIDTH_RATIO - (difficulty * (BASE_GOAL_WIDTH_RATIO - MIN_GOAL_WIDTH_RATIO)),
      gkSpeed: BASE_GK_SPEED + (easeDiff * (MAX_GK_SPEED - BASE_GK_SPEED)),
      windEffect: (Math.sin(frameRef.current * 0.015) * difficulty * WIND_PULL_MAX),
      predictionMix: Math.min(0.95, difficulty * 1.2) 
    };
  }, [difficulty]);

  const resetBall = useCallback(() => {
    ballPos.current = { x: 0.5, y: 0.85 };
    ballVel.current = { x: 0, y: 0 };
    ballZ.current = 1;
    ballCurve.current = 0;
    hasCrossedLine.current = false;
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  }, []);

  const triggerJuice = (type: 'GOAL' | 'SAVE') => {
    if (type === 'GOAL') {
      confetti({
        particleCount: 150,
        spread: 90,
        origin: { y: 0.4 },
        colors: ['#10b981', '#ffffff', '#fbbf24']
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
    } else if (type === 'SAVE') {
      confetti({
        particleCount: 50,
        spread: 40,
        startVelocity: 20,
        origin: { x: gkPos.current, y: 0.25 },
        colors: ['#f43f5e', '#ffffff'],
        disableForReducedMotion: true,
        ticks: 50
      });
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 150);
    }
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current = [{ x: clientX, y: clientY }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    // Add point to path
    dragPath.current.push({ x: clientX, y: clientY });

    // Keep path length manageable for performance
    if (dragPath.current.length > 50) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 2) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    const dx = (start.x - end.x) / window.innerWidth;
    const dy = (start.y - end.y) / window.innerHeight;
    const speed = Math.sqrt(dx * dx + dy * dy);

    if (speed < 0.012) {
      setGameState(GameState.IDLE);
      return;
    }

    // --- CURVE CALCULATION ---
    // Analyze the deviation of the mid-points from the straight line start->end
    let curvatureSum = 0;
    if (dragPath.current.length > 5) {
        const midIndex = Math.floor(dragPath.current.length / 2);
        const mid = dragPath.current[midIndex];

        // Vector Start->Mid
        const v1x = mid.x - start.x;
        const v1y = mid.y - start.y;
        // Vector Mid->End
        const v2x = end.x - mid.x;
        const v2y = end.y - mid.y;

        // 2D Cross product analog to find turn direction (z-component)
        // positive = right turn (curve right), negative = left turn
        // But in screen coords y is down.
        // Let's stick to simple deviation.

        // Angle difference approach
        const angle1 = Math.atan2(v1y, v1x);
        const angle2 = Math.atan2(v2y, v2x);
        let angleDiff = angle2 - angle1;

        // Normalize angle -PI to PI
        while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
        while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

        curvatureSum = angleDiff;
    }

    // Scale curve: -1 (left) to 1 (right)
    // In screen space: If I swipe up-right then up-left ( `)` shape ), angle changes from TopRight to TopLeft (CCW).
    // CCW change is negative angleDiff. 
    // `)` shape usually means curve Left in soccer games?
    // Let's implement: curve follows the SWIPE SHAPE.
    // If swipe is `)`, ball goes right then curves left. 
    // angleDiff < 0 (CCW) => Curve Left. 
    // angleDiff > 0 (CW) => Curve Right.

    ballCurve.current = Math.max(-1, Math.min(1, curvatureSum * 2.5));

    const kickPower = Math.min(speed * 2.1, 0.145);
    // Initial velocity based on the FINAL vector (release direction), not average
    // This feels more responsive
    const lastFew = dragPath.current.slice(-5);
    const releaseStart = lastFew[0];
    const releaseEnd = lastFew[lastFew.length - 1];
    const rDx = (releaseStart.x - releaseEnd.x) / window.innerWidth;
    const rDy = (releaseStart.y - releaseEnd.y) / window.innerHeight;
    const releaseAngle = Math.atan2(rDy, rDx);

    ballVel.current = {
      x: Math.cos(releaseAngle) * kickPower,
      y: Math.sin(releaseAngle) * kickPower
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const { goalWidth, gkSpeed, windEffect, predictionMix } = getDifficultyParams();
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // --- 1. PITCH BACKGROUND ---
      const pitchGrad = ctx.createLinearGradient(0, 0, 0, h);
      pitchGrad.addColorStop(0, '#064e3b');
      pitchGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = pitchGrad;
      ctx.fillRect(0, 0, w, h);

      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for(let i=0; i<h; i+=h/10) {
        if((i/(h/10))%2 === 0) ctx.fillRect(0, i, w, h/10);
      }

      // Wind Particles
      ctx.strokeStyle = `rgba(255,255,255,${0.05 + difficulty * 0.1})`;
      ctx.lineWidth = 1;
      windParticles.current.forEach(p => {
        p.x += p.s + (windEffect * 0.15);
        if (p.x > 1.1) p.x = -0.1;
        if (p.x < -0.1) p.x = 1.1;
        ctx.beginPath(); ctx.moveTo(p.x * w, p.y * h); ctx.lineTo((p.x + 0.02 + Math.abs(windEffect) * 0.1) * w, p.y * h); ctx.stroke();
      });

      // Goal Params
      const goalW = w * goalWidth;
      const goalX = w * (0.5 - goalWidth / 2);
      const goalY = h * 0.15; 
      const goalH = 150;
      const goalBottom = goalY + goalH;

      // --- 2. GOAL NET ---
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      for(let i=1; i<10; i++) {
        ctx.beginPath(); ctx.moveTo(goalX + (goalW/10)*i, goalY); ctx.lineTo(goalX + (goalW/10)*i, goalBottom); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(goalX, goalY + (goalH/10)*i); ctx.lineTo(goalX + goalW, goalY + (goalH/10)*i); ctx.stroke();
      }

      // --- 3. PHYSICS & LOGIC ---
      const isGoalProgress = gameState === GameState.RESULT && lastResult === 'GOAL';
      const isMoving = gameState === GameState.KICKED || isGoalProgress;

      if (isMoving) {
        const prevY = ballPos.current.y;
        const prevX = ballPos.current.x;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;

        if (gameState === GameState.KICKED) {
          // --- MAGNUS EFFECT (Curve) ---
          // Apply side force based on curve factor
          ballVel.current.x += ballCurve.current * 0.005; // Curve strength

          ballVel.current.x += windEffect * 0.0025;
          ballZ.current = Math.max(0.35, ballZ.current - 0.02);

          // --- GK AI ---
          // GK tries to predict ball X at GOAL_LINE_Y
          let targetX = ballPos.current.x;
          if (ballVel.current.y < 0) {
             const distY = ballPos.current.y - GOAL_LINE_Y;
             const steps = distY / Math.abs(ballVel.current.y);
             // Simple linear prediction for reaction
             let predictedX = ballPos.current.x + (ballVel.current.x * steps);
             // Advanced: account for curve in prediction if high difficulty
             if (difficulty > 0.6) {
                 predictedX += (ballCurve.current * 0.005) * steps * 0.5;
             }

             targetX = ballPos.current.x * (1 - predictionMix) + predictedX * predictionMix;
          }

          const dx = targetX - gkPos.current;
          gkPos.current += dx * gkSpeed;
          gkPos.current = Math.max(0.2, Math.min(0.8, gkPos.current));
          gkVelocity.current = (gkPos.current - (gkPos.current - dx * gkSpeed)) * 2;

          // --- COLLISION ---
          if (!hasCrossedLine.current && ballPos.current.y <= GOAL_LINE_Y) {
            hasCrossedLine.current = true;

            const fraction = (GOAL_LINE_Y - prevY) / (ballPos.current.y - prevY || -0.0001);
            const impactX = prevX + fraction * (ballPos.current.x - prevX);
            // Snap visual position for accurate impact frame
            ballPos.current.x = impactX;
            ballPos.current.y = GOAL_LINE_Y;

            const withinPosts = impactX > (0.5 - goalWidth / 2) && impactX < (0.5 + goalWidth / 2);

            // Visual Width of GK is roughly 80px -> relative to screen width? 
            // Let's say GK body width is ~0.08 of screen, + arms reach.
            const gkBodyRadius = 0.05;
            const gkReachRadius = 0.14; 
            const distToGK = Math.abs(impactX - gkPos.current);

            const isSave = distToGK < gkReachRadius && withinPosts;

            if (isSave) {
               setLastResult('SAVE');

               // --- BOUNCE PHYSICS ---
               // Determine bounce direction relative to GK center
               const hitSide = impactX < gkPos.current ? -1 : 1;
               const hitBody = distToGK < gkBodyRadius;

               ballVel.current.y *= -0.4; // Bounce back
               ballVel.current.x = hitSide * (0.05 + Math.random() * 0.05); // Deflect sideways

               if (hitBody) {
                   ballVel.current.y *= 1.2; // Harder bounce off body
               }

               setDifficulty(d => Math.max(0.1, d - 0.05));
               triggerJuice('SAVE');
            } else if (withinPosts) {
               setLastResult('GOAL');
               setMetrics(m => {
                  const newStreak = m.streak + 1;
                  return { ...m, score: m.score + 1, streak: newStreak, bestStreak: Math.max(m.bestStreak, newStreak) };
               });
               triggerJuice('GOAL');
               setDifficulty(d => Math.min(1.0, d + 0.08));
            } else {
               setLastResult('MISS');
               setMetrics(m => ({ ...m, streak: 0 }));
               setDifficulty(d => Math.max(0.1, d - 0.03));
            }
            setGameState(GameState.RESULT);
          }
        } 

        // Post-event physics
        if (gameState === GameState.RESULT) {
             ballVel.current.x *= 0.95;
             ballVel.current.y *= 0.95; // Damping

             if (lastResult === 'GOAL') {
                 // Net constraints
                 if (ballPos.current.y < NET_DEPTH_Y) {
                     ballPos.current.y = NET_DEPTH_Y;
                     ballVel.current.y *= -0.4;
                 }
                 ballZ.current = Math.max(0.35, ballZ.current - 0.005);
             }
        }

        if (gameState === GameState.KICKED && (ballPos.current.y < 0.0 || Math.abs(ballPos.current.x - 0.5) > 0.6)) {
           if (!hasCrossedLine.current) {
               setLastResult('MISS');
               setGameState(GameState.RESULT);
               setMetrics(m => ({ ...m, streak: 0 }));
           }
        }

      } else if (gameState === GameState.IDLE) {
        gkPos.current = 0.5 + Math.sin(frameRef.current * 0.03) * 0.08;
        gkVelocity.current = Math.cos(frameRef.current * 0.03) * 0.01;
      }

      // --- 4. RENDER GOALKEEPER ---
      const gkX = gkPos.current * w;
      const gkY = goalBottom - 5;

      ctx.save();
      ctx.translate(gkX, gkY);

      let leanAngle = gkVelocity.current * 25; 
      leanAngle = Math.max(-1.2, Math.min(1.2, leanAngle));
      ctx.rotate(leanAngle);

      // Body
      ctx.fillStyle = '#ef4444'; 
      ctx.beginPath();
      ctx.moveTo(-18, -55);
      ctx.lineTo(18, -55);
      ctx.lineTo(14, 0);
      ctx.lineTo(-14, 0);
      ctx.fill();

      // Head
      ctx.fillStyle = '#fde047'; 
      ctx.beginPath(); ctx.arc(0, -65, 12, 0, Math.PI * 2); ctx.fill();

      // Arms (IK)
      ctx.strokeStyle = '#ef4444'; 
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      let leftArmAngle = Math.PI - 0.5;
      let rightArmAngle = 0.5;

      // Logic: Hands follow ball if close, otherwise idle/balance
      if (gameState === GameState.KICKED || gameState === GameState.RESULT) {
          // Transform ball pos to GK local space roughly
          // GK head is roughly at gkX, gkY-65
          // Ball Y needs to be mapped. Ball Y=0.23 is goal line. GK Y is bottom of goal.
          // This is a rough visual IK
          const ballRelX = (ballPos.current.x - gkPos.current) * w;
          const ballRelY = (ballPos.current.y * h) - (gkY - 65);

          // Clamp tracking
          if (ballPos.current.y > 0.2 && ballPos.current.y < 0.6) {
              const lookAtAngle = Math.atan2(ballRelY, ballRelX);
              // If ball is left
              if (ballRelX < 0) {
                  leftArmAngle = lookAtAngle; // Left arm points to ball
                  rightArmAngle = Math.PI / 3; // Balance
              } else {
                  rightArmAngle = lookAtAngle; // Right arm points to ball
                  leftArmAngle = Math.PI - Math.PI / 3;
              }
          }
      }

      // Left Arm
      ctx.beginPath();
      ctx.moveTo(-16, -50);
      const lHandX = -16 + Math.cos(leftArmAngle) * 35;
      const lHandY = -50 + Math.sin(leftArmAngle) * 35; // +sin because Y is down
      ctx.lineTo(lHandX, lHandY);
      ctx.stroke();

      // Right Arm
      ctx.beginPath();
      ctx.moveTo(16, -50);
      const rHandX = 16 + Math.cos(rightArmAngle) * 35;
      const rHandY = -50 + Math.sin(rightArmAngle) * 35;
      ctx.lineTo(rHandX, rHandY);
      ctx.stroke();

      // Gloves
      ctx.fillStyle = '#fde047';
      ctx.beginPath(); ctx.arc(lHandX, lHandY, 8, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(rHandX, rHandY, 8, 0, Math.PI*2); ctx.fill();

      ctx.restore();

      // --- 5. RENDER BALL ---
      const ballScreenX = ballPos.current.x * w;
      const ballScreenY = ballPos.current.y * h;
      const bSize = 22 * ballZ.current;

      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(ballScreenX, ballScreenY + (bSize * 0.8), bSize, bSize * 0.3, 0, 0, Math.PI * 2); ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(ballScreenX, ballScreenY, bSize, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1;

      // Spin visualization based on curve
      const rotationSpeed = isMoving ? 0.3 + Math.abs(ballCurve.current) * 0.2 : 0;
      const rotation = frameRef.current * rotationSpeed;

      for(let i=0; i<3; i++) {
        ctx.beginPath();
        const rot = rotation + (i * Math.PI * 2/3);
        // Tilt the drawing lines based on curve direction
        const tilt = ballCurve.current * 0.5; 
        const bx = Math.cos(rot + tilt) * bSize;
        const by = Math.sin(rot) * bSize;

        ctx.moveTo(ballScreenX, ballScreenY);
        ctx.lineTo(ballScreenX + bx, ballScreenY + by);
        ctx.stroke();
      }

      // --- 6. FRONT POSTS ---
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 10;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(goalX, goalBottom);
      ctx.lineTo(goalX, goalY);
      ctx.lineTo(goalX + goalW, goalY);
      ctx.lineTo(goalX + goalW, goalBottom);
      ctx.stroke();

      // --- 7. DRAG TRAIL (FEEDBACK) ---
      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
         ctx.beginPath();
         // Gradient path
         const grad = ctx.createLinearGradient(
             dragPath.current[0].x, dragPath.current[0].y, 
             dragPath.current[dragPath.current.length-1].x, dragPath.current[dragPath.current.length-1].y
         );
         grad.addColorStop(0, 'rgba(255, 255, 255, 0)');
         grad.addColorStop(1, 'rgba(52, 211, 153, 0.8)');

         ctx.strokeStyle = grad;
         ctx.lineWidth = 4;
         ctx.lineCap = 'round';
         ctx.lineJoin = 'round';

         // Draw spline roughly or lines
         ctx.moveTo(dragPath.current[0].x, dragPath.current[0].y);
         for(let i=1; i<dragPath.current.length; i++) {
             // Basic smoothing
             const p = dragPath.current[i];
             const prev = dragPath.current[i-1];
             const midX = (p.x + prev.x) / 2;
             const midY = (p.y + prev.y) / 2;
             ctx.quadraticCurveTo(prev.x, prev.y, midX, midY);
         }
         ctx.stroke();

         // Arrow head
         const last = dragPath.current[dragPath.current.length-1];
         ctx.beginPath(); ctx.arc(last.x, last.y, 6, 0, Math.PI*2); ctx.fillStyle = '#34d399'; ctx.fill();
      }

      frameRef.current = requestAnimationFrame(update);
    };

    const handleResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', handleResize);
    handleResize();
    update();
    return () => { window.removeEventListener('resize', handleResize); cancelAnimationFrame(frameRef.current); };
  }, [gameState, getDifficultyParams, lastResult]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-12 py-6 rounded-[50px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-14 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={24} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/60 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFFICULTY: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* CENTER FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
          <div className="animate-[scaleIn_0.35s_cubic-bezier(.17,.67,.26,.99)] flex flex-col items-center">
            <h2 className={`text-[12rem] font-black italic uppercase tracking-tighter leading-none ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_60px_rgba(52,211,153,0.7)]' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-[0_0_60px_rgba(244,63,94,0.7)]' :
              'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
            <div className="mt-6 bg-white/10 backdrop-blur-md text-white px-10 py-4 rounded-full font-black text-sm tracking-[0.4em] uppercase border border-white/20 shadow-2xl animate-pulse">
              Click to continue
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM HINT / ACTION */}
      <div className="absolute bottom-16 left-1/2 -translate-x-1/2 pointer-events-none z-10">
        {gameState === GameState.IDLE && (
          <div className="flex flex-col items-center gap-4 opacity-50 animate-bounce">
            <div className="w-14 h-14 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-4 h-4 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-xs uppercase tracking-[0.4em]">Swipe Up to Kick</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scaleIn { 0% { transform: scale(0.3); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-2px, 0, 0); } 20%, 80% { transform: translate3d(4px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-6px, 0, 0); } 40%, 60% { transform: translate3d(6px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

export enum GameState {
  IDLE = 'IDLE',
  DRAGGING = 'DRAGGING',
  KICKED = 'KICKED',
  RESULT = 'RESULT'
}

export interface Vec2 {
  x: number;
  y: number;
}

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

export interface GameMetrics {
  score: number;
  streak: number;
  bestStreak: number;
  attempts: number;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, Vec3, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- 3D WORLD CONSTANTS ---
// World units: Meters (roughly)
// Field: X [-15, 15], Z [0, 40]
const GOAL_DIST = 28;
const GOAL_WIDTH = 7.32;
const GOAL_HEIGHT = 2.44;
const BALL_RADIUS = 0.15;
const GRAVITY = 0.012; // Adjusted for game feel
const AIR_RESISTANCE = 0.99;
const FLOOR_BOUNCE = 0.6;
const CAM_POS = { x: 0, y: 1.8, z: -6 };
const FOCAL_LENGTH = 800; // Field of View scaling

// --- DIFFICULTY TUNING ---
const BASE_GK_SPEED = 0.15; // Meters per frame
const MAX_GK_SPEED = 0.45;
const MAX_WIND_FORCE = 0.008;

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // 3D Physics State
  const ballPos = useRef<Vec3>({ x: 0, y: BALL_RADIUS, z: 0 });
  const ballVel = useRef<Vec3>({ x: 0, y: 0, z: 0 });
  const ballSpin = useRef<number>(0); // Curve factor (Magnus force X)

  const gkPos = useRef<Vec3>({ x: 0, y: 0, z: GOAL_DIST - 0.5 });
  const gkVelX = useRef<number>(0);

  // Input State
  const dragStart = useRef<Vec2 | null>(null);
  const dragPath = useRef<Vec2[]>([]);
  const frameRef = useRef<number>(0);
  const windVector = useRef<Vec3>({ x: 0, y: 0, z: 0 });

  // 3D Projection Helper
  const project = useCallback((p: Vec3, width: number, height: number) => {
    // Camera Transform
    const rx = p.x - CAM_POS.x;
    const ry = p.y - CAM_POS.y;
    const rz = p.z - CAM_POS.z;

    // Perspective Projection
    if (rz <= 0) return { x: -9999, y: -9999, scale: 0, visible: false };

    const scale = FOCAL_LENGTH / rz;
    const x = width / 2 + rx * scale;
    const y = height / 2 - ry * scale; // Canvas Y is down

    return { x, y, scale: scale / 100, visible: true, zIndex: rz }; // Scale normalized roughly
  }, []);

  const getDifficultyParams = useCallback(() => {
    const d = difficulty;
    // Non-linear difficulty curve
    const curve = d < 0.5 ? 2 * d * d : 1 - Math.pow(-2 * d + 2, 2) / 2;
    return {
      gkSpeed: BASE_GK_SPEED + curve * (MAX_GK_SPEED - BASE_GK_SPEED),
      windStrength: d * MAX_WIND_FORCE,
      predictionError: Math.max(0, 1.0 - d * 1.5) // GK makes mistakes at low diff
    };
  }, [difficulty]);

  useEffect(() => {
    // Update wind slowly
    const interval = setInterval(() => {
        const angle = Date.now() / 2000;
        windVector.current = {
            x: Math.sin(angle) * getDifficultyParams().windStrength,
            y: 0,
            z: Math.cos(angle * 0.7) * getDifficultyParams().windStrength * 0.5
        };
    }, 100);
    return () => clearInterval(interval);
  }, [getDifficultyParams]);

  const resetBall = () => {
    ballPos.current = { x: 0, y: BALL_RADIUS, z: 0 };
    ballVel.current = { x: 0, y: 0, z: 0 };
    ballSpin.current = 0;
    gkPos.current = { x: 0, y: 0, z: GOAL_DIST - 0.5 };
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x, y };
    dragPath.current = [{ x, y }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current.push({ x, y });
    if (dragPath.current.length > 40) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 3) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    // Calculate Swipe Physics
    const dx = (end.x - start.x) / window.innerWidth;
    const dy = (end.y - start.y) / window.innerHeight; // Negative when swiping up

    const swipeDist = Math.sqrt(dx*dx + dy*dy);
    const swipeSpeed = swipeDist; // Simplification since we don't track time accurately here, assumed fast swipe

    if (swipeDist < 0.05) {
        setGameState(GameState.IDLE);
        return;
    }

    // --- CURVE CALCULATION (From previous iteration) ---
    // Detect curvature in path
    let curveSum = 0;
    for(let i=1; i<dragPath.current.length-1; i++) {
        const p1 = dragPath.current[i-1];
        const p2 = dragPath.current[i];
        const p3 = dragPath.current[i+1];
        const v1 = { x: p2.x - p1.x, y: p2.y - p1.y };
        const v2 = { x: p3.x - p2.x, y: p3.y - p2.y };
        const cross = v1.x * v2.y - v1.y * v2.x;
        curveSum += cross;
    }
    // Normalize curve: + is clockwise (Right curve?), - is CCW (Left curve)
    // Actually in screen space Y down:
    // Swiping Top-Right then Top-Left ( `)` shape ) -> Vector rotates CCW -> Cross is Negative.
    // Negative Cross should push ball Left.
    const MAX_CURVE = 0.03;
    ballSpin.current = Math.max(-MAX_CURVE, Math.min(MAX_CURVE, curveSum * 0.00005));

    // --- LAUNCH VELOCITY MAPPING ---
    // Z (Forward): Proportional to how "Up" we swiped and speed
    const powerZ = Math.min(1.2, Math.abs(dy) * 2.5 + swipeSpeed); 

    // Y (Up): Proportional to "High Aim" (dy) but needs to be careful not to moonshot every time
    // If I swipe short, Y is low. If I swipe long, Y is high.
    const lift = Math.min(0.6, Math.abs(dy) * 1.5); 

    // X (Side): Direct mapping of horizontal swipe
    const side = dx * 1.2;

    ballVel.current = {
        x: side,
        y: lift * 0.6 + 0.05, // Base lift
        z: powerZ * 0.8 // Base power
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  // --- PHYSICS ENGINE ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const update = () => {
      const w = canvas.width;
      const h = canvas.height;
      const { gkSpeed, predictionError } = getDifficultyParams();

      ctx.clearRect(0, 0, w, h);

      // --- RENDER BACKGROUND (Pitch) ---
      // Use Gradient for sky/ground
      const horizonY = h * 0.3;
      const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
      skyGrad.addColorStop(0, '#020617');
      skyGrad.addColorStop(1, '#1e293b');
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, w, horizonY);

      const fieldGrad = ctx.createLinearGradient(0, horizonY, 0, h);
      fieldGrad.addColorStop(0, '#064e3b');
      fieldGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = fieldGrad;
      ctx.fillRect(0, horizonY, w, h - horizonY);

      // Draw 3D Grid Lines on Field
      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.lineWidth = 1;
      for (let z = 0; z <= 40; z += 5) {
          const p1 = project({ x: -20, y: 0, z }, w, h);
          const p2 = project({ x: 20, y: 0, z }, w, h);
          if (p1.visible && p2.visible) {
              ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }
      for (let x = -15; x <= 15; x += 5) {
          const p1 = project({ x, y: 0, z: 0 }, w, h);
          const p2 = project({ x, y: 0, z: 40 }, w, h);
          if (p1.visible && p2.visible) {
            ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }

      // --- PHYSICS UPDATE ---
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL');

      if (isMoving) {
        // Air Resistance
        ballVel.current.x *= AIR_RESISTANCE;
        ballVel.current.y *= AIR_RESISTANCE;
        ballVel.current.z *= AIR_RESISTANCE;

        // Gravity
        ballVel.current.y -= GRAVITY;

        // Wind & Magnus Effect
        ballVel.current.x += windVector.current.x + ballSpin.current;
        ballVel.current.z += windVector.current.z;

        // Position Update
        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;
        ballPos.current.z += ballVel.current.z;

        // Floor Collision
        if (ballPos.current.y < BALL_RADIUS) {
            ballPos.current.y = BALL_RADIUS;
            ballVel.current.y *= -FLOOR_BOUNCE;
            ballVel.current.x *= 0.8; // Friction
            ballVel.current.z *= 0.8;
            // Stop if too slow
            if (Math.abs(ballVel.current.y) < 0.02) ballVel.current.y = 0;
        }

        // --- GK AI ---
        if (gameState === GameState.KICKED) {
            // Predict ball intersection with goal plane (Z = GOAL_DIST)
            const timeToGoal = (GOAL_DIST - ballPos.current.z) / ballVel.current.z;

            let targetX = gkPos.current.x;

            if (timeToGoal > 0 && timeToGoal < 30) {
                 const predictedX = ballPos.current.x + ballVel.current.x * timeToGoal;
                 // Add error based on difficulty
                 const error = (Math.random() - 0.5) * predictionError * 2;
                 targetX = Math.max(-GOAL_WIDTH/2, Math.min(GOAL_WIDTH/2, predictedX + error));
            }

            // Move GK
            const dist = targetX - gkPos.current.x;
            const move = Math.sign(dist) * Math.min(Math.abs(dist), gkSpeed);
            gkPos.current.x += move;
            gkVelX.current = move; // For tilt animation

            // GK Jump (Simple logic: if ball is high, jump?)
            // For now, let's assume GK covers height with hands
        }

        // --- GOAL DETECTION ---
        // Check if ball passed goal plane
        if (gameState === GameState.KICKED && ballPos.current.z >= GOAL_DIST) {
            // 1. Check if inside Posts
            const inX = Math.abs(ballPos.current.x) < GOAL_WIDTH / 2 + BALL_RADIUS;
            const underBar = ballPos.current.y < GOAL_HEIGHT + BALL_RADIUS;

            // 2. Check GK Save
            // Simple AABB collision for GK (Width ~ 1.5m, Height ~ 2m)
            const gkW = 1.2;
            const gkH = 2.2;
            const hitGK = 
                Math.abs(ballPos.current.x - gkPos.current.x) < gkW/2 + BALL_RADIUS &&
                ballPos.current.y < gkH + BALL_RADIUS;

            if (hitGK && inX && underBar) {
                setLastResult('SAVE');
                setGameState(GameState.RESULT);

                // Physics Deflection
                ballVel.current.z *= -0.3;
                ballVel.current.x += (Math.random() - 0.5) * 0.5;
                ballVel.current.y += 0.1;

                confetti({
                    particleCount: 50, spread: 40, origin: { y: 0.5 }, colors: ['#f43f5e']
                });
                setDifficulty(d => Math.max(0.1, d - 0.05));
            } 
            else if (inX && underBar) {
                setLastResult('GOAL');
                setGameState(GameState.RESULT);

                // Net interaction (Stop forward momentum)
                ballVel.current.z *= 0.1; 

                confetti({
                    particleCount: 150, spread: 80, origin: { y: 0.4 }, colors: ['#10b981', '#fbbf24']
                });
                setIsShaking(true); setTimeout(() => setIsShaking(false), 300);

                setMetrics(m => ({
                    ...m, score: m.score + 1, streak: m.streak + 1, bestStreak: Math.max(m.bestStreak, m.streak + 1)
                }));
                setDifficulty(d => Math.min(1.0, d + 0.08));
            } 
            else {
                setLastResult('MISS');
                setGameState(GameState.RESULT);
                setMetrics(m => ({ ...m, streak: 0 }));
                setDifficulty(d => Math.max(0.1, d - 0.03));
            }
        }

        // Net Collision (Back of net)
        if (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.z > GOAL_DIST + 2) {
             ballVel.current.z *= -0.5;
             ballPos.current.z = GOAL_DIST + 2;
        }
      } 
      else if (gameState === GameState.IDLE) {
         // GK Idle
         gkPos.current.x = Math.sin(Date.now() / 500) * 0.5;
      }

      // --- RENDER SCENE ---

      // 1. Goal Post Rendering (Projected)
      // Goal Frame: (-W/2, 0, D) -> (-W/2, H, D) -> (W/2, H, D) -> (W/2, 0, D)
      const gD = GOAL_DIST;
      const gW = GOAL_WIDTH / 2;
      const gH = GOAL_HEIGHT;

      const bl = project({x: -gW, y: 0, z: gD}, w, h);
      const tl = project({x: -gW, y: gH, z: gD}, w, h);
      const tr = project({x: gW, y: gH, z: gD}, w, h);
      const br = project({x: gW, y: 0, z: gD}, w, h);

      ctx.strokeStyle = 'white';
      ctx.lineWidth = tl.scale * 12; // Scale thickness
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      ctx.beginPath();
      ctx.moveTo(bl.x, bl.y);
      ctx.lineTo(tl.x, tl.y);
      ctx.lineTo(tr.x, tr.y);
      ctx.lineTo(br.x, br.y);
      ctx.stroke();

      // Net (faint)
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1;
      const steps = 10;
      for (let i=0; i<=steps; i++) {
         const t = i/steps;
         const lx = bl.x + (br.x - bl.x) * t;
         const ly = bl.y + (tl.y - bl.y) * t; // Top to Bottom
         const tx = tl.x + (tr.x - tl.x) * t;
         ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(tx, ly - (ly-tl.y)); ctx.stroke(); // Vertical

         const hy = bl.y + (tl.y - bl.y) * t;
         ctx.beginPath(); ctx.moveTo(bl.x, hy); ctx.lineTo(br.x, hy); ctx.stroke(); // Horizontal
      }

      // 2. GK Rendering
      const gkProj = project(gkPos.current, w, h);
      if (gkProj.visible) {
        ctx.save();
        ctx.translate(gkProj.x, gkProj.y - (1.1 * gkProj.scale * 100)); // Center on body

        // Simple Body
        const gkS = gkProj.scale * 100;
        const lean = -gkVelX.current * 10; // Tilt based on movement
        ctx.rotate(lean * Math.PI / 180);

        // Jersey
        ctx.fillStyle = '#ef4444';
        ctx.fillRect(-0.4 * gkS, -0.6 * gkS, 0.8 * gkS, 1.2 * gkS);

        // Head
        ctx.fillStyle = '#fde047';
        ctx.beginPath(); ctx.arc(0, -0.9 * gkS, 0.25 * gkS, 0, Math.PI*2); ctx.fill();

        // Arms (Reach)
        ctx.strokeStyle = '#ef4444';
        ctx.lineWidth = 0.2 * gkS;
        // Logic: Arms up if ball high, arms side if ball low
        const armsUp = ballPos.current.y > 1.5;

        ctx.beginPath();
        ctx.moveTo(-0.4*gkS, -0.5*gkS);
        ctx.lineTo(-0.9*gkS, armsUp ? -1.2*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0.4*gkS, -0.5*gkS);
        ctx.lineTo(0.9*gkS, armsUp ? -1.2*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.restore();
      }

      // 3. Ball Shadow
      if (ballPos.current.y > 0) {
          const shadowProj = project({x: ballPos.current.x, y: 0.02, z: ballPos.current.z}, w, h);
          if (shadowProj.visible) {
              const sSize = BALL_RADIUS * shadowProj.scale * 100 * (1 - Math.min(1, ballPos.current.y / 5)); // Fade/Shrink with height
              ctx.fillStyle = 'rgba(0,0,0,0.4)';
              ctx.beginPath();
              ctx.ellipse(shadowProj.x, shadowProj.y, sSize, sSize * 0.3, 0, 0, Math.PI*2);
              ctx.fill();
          }
      }

      // 4. Ball Rendering
      const ballProj = project(ballPos.current, w, h);
      if (ballProj.visible) {
          const bRad = BALL_RADIUS * ballProj.scale * 100;
          ctx.translate(ballProj.x, ballProj.y);

          // Rotation (simulated visually)
          const rot = (ballPos.current.x + ballPos.current.z) * 5;
          ctx.rotate(rot);

          ctx.fillStyle = 'white';
          ctx.beginPath(); ctx.arc(0, 0, bRad, 0, Math.PI*2); ctx.fill();

          // Pattern
          ctx.strokeStyle = '#1e293b';
          ctx.lineWidth = bRad * 0.1;
          ctx.beginPath(); ctx.moveTo(-bRad, 0); ctx.lineTo(bRad, 0); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, -bRad); ctx.lineTo(0, bRad); ctx.stroke();

          ctx.rotate(-rot);
          ctx.translate(-ballProj.x, -ballProj.y);
      }

      // 5. Drag Line (UI Overlay)
      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
          ctx.beginPath();
          const start = dragPath.current[0];
          ctx.moveTo(start.x, start.y);
          for (let p of dragPath.current) ctx.lineTo(p.x, p.y);
          ctx.strokeStyle = 'rgba(52, 211, 153, 0.6)';
          ctx.lineWidth = 4;
          ctx.stroke();
      }

      requestAnimationFrame(update);
    };

    update();
  }, [gameState, getDifficultyParams, lastResult, project]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" width={window.innerWidth} height={window.innerHeight} />

      {/* STATS HUD */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-12 py-6 rounded-[50px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-4xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-14 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={24} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-4xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {/* DIFFICULTY RADAR */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-4 py-2 rounded-full border border-white/10 text-[11px] font-black text-white/60 tracking-wider">
           <Activity size={14} className="text-rose-500" />
           AI DIFF: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-44 h-2 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {/* FEEDBACK */}
      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
           <h2 className={`text-[8rem] font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_30px_rgba(52,211,153,0.5)]' :
              lastResult === 'SAVE' ? 'text-rose-500' : 'text-zinc-600'
            }`}>
              {lastResult}!
            </h2>
             <div className="mt-4 bg-white/10 backdrop-blur-md text-white px-6 py-2 rounded-full text-xs tracking-widest uppercase border border-white/10 animate-pulse">
              Tap to Continue
            </div>
        </div>
      )}

      {/* HINT */}
      {gameState === GameState.IDLE && (
          <div className="absolute bottom-16 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 opacity-50 animate-bounce pointer-events-none">
            <div className="w-12 h-12 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-[10px] uppercase tracking-[0.3em]">Swipe Up to Kick</p>
          </div>
      )}

      <style>{`
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, Vec3, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- 3D WORLD CONSTANTS ---
// World units: Meters
// Standard Penalty Spot is 11m.
const GOAL_DIST = 11.0; 
const GOAL_WIDTH = 8.5; // Slightly wider than standard (7.32) for arcade fun
const GOAL_HEIGHT = 2.8; // Slightly taller than standard (2.44)
const BALL_RADIUS = 0.22; // Size 5 ball (approx 22cm radius visually tuned)
const GRAVITY = 0.012; 
const AIR_RESISTANCE = 0.985;
const FLOOR_BOUNCE = 0.6;
// Camera: Behind the ball (-z), slightly up (+y)
const CAM_POS = { x: 0, y: 1.4, z: -3.5 }; 
const FOCAL_LENGTH = 700; // Adjusted FOV

// --- DIFFICULTY TUNING ---
const BASE_GK_SPEED = 0.12; 
const MAX_GK_SPEED = 0.35;
const MAX_WIND_FORCE = 0.008;

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // 3D Physics State
  const ballPos = useRef<Vec3>({ x: 0, y: BALL_RADIUS, z: 0 });
  const ballVel = useRef<Vec3>({ x: 0, y: 0, z: 0 });
  const ballSpin = useRef<number>(0); 

  const gkPos = useRef<Vec3>({ x: 0, y: 0, z: GOAL_DIST - 0.5 });
  const gkVelX = useRef<number>(0);

  // Input State
  const dragStart = useRef<Vec2 | null>(null);
  const dragPath = useRef<Vec2[]>([]);
  const frameRef = useRef<number>(0);
  const windVector = useRef<Vec3>({ x: 0, y: 0, z: 0 });

  // 3D Projection Helper
  const project = useCallback((p: Vec3, width: number, height: number) => {
    const rx = p.x - CAM_POS.x;
    const ry = p.y - CAM_POS.y;
    const rz = p.z - CAM_POS.z;

    if (rz <= 0.1) return { x: -9999, y: -9999, scale: 0, visible: false };

    const scale = FOCAL_LENGTH / rz;
    const x = width / 2 + rx * scale;
    const y = height / 2 - ry * scale; 

    return { x, y, scale: scale / 100, visible: true, zIndex: rz }; 
  }, []);

  const getDifficultyParams = useCallback(() => {
    const d = difficulty;
    const curve = d < 0.5 ? 2 * d * d : 1 - Math.pow(-2 * d + 2, 2) / 2;
    return {
      gkSpeed: BASE_GK_SPEED + curve * (MAX_GK_SPEED - BASE_GK_SPEED),
      windStrength: d * MAX_WIND_FORCE,
      predictionError: Math.max(0, 1.0 - d * 1.5)
    };
  }, [difficulty]);

  useEffect(() => {
    const interval = setInterval(() => {
        const angle = Date.now() / 2000;
        windVector.current = {
            x: Math.sin(angle) * getDifficultyParams().windStrength,
            y: 0,
            z: Math.cos(angle * 0.7) * getDifficultyParams().windStrength * 0.5
        };
    }, 100);
    return () => clearInterval(interval);
  }, [getDifficultyParams]);

  const resetBall = () => {
    ballPos.current = { x: 0, y: BALL_RADIUS, z: 0 };
    ballVel.current = { x: 0, y: 0, z: 0 };
    ballSpin.current = 0;
    gkPos.current = { x: 0, y: 0, z: GOAL_DIST - 0.5 };
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x, y };
    dragPath.current = [{ x, y }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current.push({ x, y });
    if (dragPath.current.length > 40) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 3) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    const dx = (end.x - start.x) / window.innerWidth;
    const dy = (end.y - start.y) / window.innerHeight; 

    const swipeDist = Math.sqrt(dx*dx + dy*dy);
    const swipeSpeed = swipeDist; 

    if (swipeDist < 0.05) {
        setGameState(GameState.IDLE);
        return;
    }

    let curveSum = 0;
    for(let i=1; i<dragPath.current.length-1; i++) {
        const p1 = dragPath.current[i-1];
        const p2 = dragPath.current[i];
        const p3 = dragPath.current[i+1];
        const v1 = { x: p2.x - p1.x, y: p2.y - p1.y };
        const v2 = { x: p3.x - p2.x, y: p3.y - p2.y };
        const cross = v1.x * v2.y - v1.y * v2.x;
        curveSum += cross;
    }
    const MAX_CURVE = 0.03;
    ballSpin.current = Math.max(-MAX_CURVE, Math.min(MAX_CURVE, curveSum * 0.00005));

    // Power mapping tuned for shorter distance (11m)
    const powerZ = Math.min(0.9, Math.abs(dy) * 2.0 + swipeSpeed * 0.5); 
    const lift = Math.min(0.5, Math.abs(dy) * 1.2); 
    const side = dx * 1.0;

    ballVel.current = {
        x: side,
        y: lift * 0.5 + 0.08, 
        z: powerZ * 0.6 + 0.1 
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const update = () => {
      // Handle resize inline for simplicity or check dimensions
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
          canvas.width = window.innerWidth;
          canvas.height = window.innerHeight;
      }

      const w = canvas.width;
      const h = canvas.height;
      const { gkSpeed, predictionError } = getDifficultyParams();

      ctx.clearRect(0, 0, w, h);

      // --- RENDER BACKGROUND ---
      const horizonY = h * 0.35; // Horizon slightly lower
      const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
      skyGrad.addColorStop(0, '#0f172a');
      skyGrad.addColorStop(1, '#1e293b');
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, w, horizonY);

      const fieldGrad = ctx.createLinearGradient(0, horizonY, 0, h);
      fieldGrad.addColorStop(0, '#064e3b');
      fieldGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = fieldGrad;
      ctx.fillRect(0, horizonY, w, h - horizonY);

      // Grid
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let z = 0; z <= 20; z += 2.5) {
          const p1 = project({ x: -10, y: 0, z }, w, h);
          const p2 = project({ x: 10, y: 0, z }, w, h);
          if (p1.visible && p2.visible) {
              ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }
      for (let x = -10; x <= 10; x += 2.5) {
          const p1 = project({ x, y: 0, z: -5 }, w, h);
          const p2 = project({ x, y: 0, z: 20 }, w, h);
          if (p1.visible && p2.visible) {
            ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }

      // --- PHYSICS UPDATE ---
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL');

      if (isMoving) {
        ballVel.current.x *= AIR_RESISTANCE;
        ballVel.current.y *= AIR_RESISTANCE;
        ballVel.current.z *= AIR_RESISTANCE;
        ballVel.current.y -= GRAVITY;
        ballVel.current.x += windVector.current.x + ballSpin.current;
        ballVel.current.z += windVector.current.z;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;
        ballPos.current.z += ballVel.current.z;

        if (ballPos.current.y < BALL_RADIUS) {
            ballPos.current.y = BALL_RADIUS;
            ballVel.current.y *= -FLOOR_BOUNCE;
            ballVel.current.x *= 0.8; 
            ballVel.current.z *= 0.8;
            if (Math.abs(ballVel.current.y) < 0.02) ballVel.current.y = 0;
        }

        if (gameState === GameState.KICKED) {
            const timeToGoal = (GOAL_DIST - ballPos.current.z) / ballVel.current.z;
            let targetX = gkPos.current.x;
            if (timeToGoal > 0 && timeToGoal < 30) {
                 const predictedX = ballPos.current.x + ballVel.current.x * timeToGoal;
                 const error = (Math.random() - 0.5) * predictionError * 2;
                 targetX = Math.max(-GOAL_WIDTH/2, Math.min(GOAL_WIDTH/2, predictedX + error));
            }
            const dist = targetX - gkPos.current.x;
            const move = Math.sign(dist) * Math.min(Math.abs(dist), gkSpeed);
            gkPos.current.x += move;
            gkVelX.current = move; 
        }

        if (gameState === GameState.KICKED && ballPos.current.z >= GOAL_DIST) {
            const inX = Math.abs(ballPos.current.x) < GOAL_WIDTH / 2 + BALL_RADIUS;
            const underBar = ballPos.current.y < GOAL_HEIGHT + BALL_RADIUS;

            const gkW = 1.0; // GK width
            const gkH = 2.0; // GK height
            const hitGK = 
                Math.abs(ballPos.current.x - gkPos.current.x) < gkW/2 + BALL_RADIUS &&
                ballPos.current.y < gkH + BALL_RADIUS;

            if (hitGK && inX && underBar) {
                setLastResult('SAVE');
                setGameState(GameState.RESULT);
                ballVel.current.z *= -0.3;
                ballVel.current.x += (Math.random() - 0.5) * 0.5;
                ballVel.current.y += 0.1;
                confetti({ particleCount: 50, spread: 40, origin: { y: 0.5 }, colors: ['#f43f5e'] });
                setDifficulty(d => Math.max(0.1, d - 0.05));
            } 
            else if (inX && underBar) {
                setLastResult('GOAL');
                setGameState(GameState.RESULT);
                ballVel.current.z *= 0.1; 
                confetti({ particleCount: 150, spread: 80, origin: { y: 0.4 }, colors: ['#10b981', '#fbbf24'] });
                setIsShaking(true); setTimeout(() => setIsShaking(false), 300);
                setMetrics(m => ({
                    ...m, score: m.score + 1, streak: m.streak + 1, bestStreak: Math.max(m.bestStreak, m.streak + 1)
                }));
                setDifficulty(d => Math.min(1.0, d + 0.08));
            } 
            else {
                setLastResult('MISS');
                setGameState(GameState.RESULT);
                setMetrics(m => ({ ...m, streak: 0 }));
                setDifficulty(d => Math.max(0.1, d - 0.03));
            }
        }

        if (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.z > GOAL_DIST + 2) {
             ballVel.current.z *= -0.5;
             ballPos.current.z = GOAL_DIST + 2;
        }
      } 
      else if (gameState === GameState.IDLE) {
         gkPos.current.x = Math.sin(Date.now() / 500) * 0.5;
      }

      // --- RENDER SCENE ---

      const gD = GOAL_DIST;
      const gW = GOAL_WIDTH / 2;
      const gH = GOAL_HEIGHT;

      const bl = project({x: -gW, y: 0, z: gD}, w, h);
      const tl = project({x: -gW, y: gH, z: gD}, w, h);
      const tr = project({x: gW, y: gH, z: gD}, w, h);
      const br = project({x: gW, y: 0, z: gD}, w, h);

      // Draw Goal
      if (bl.visible && tr.visible) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = tl.scale * 15; // Thicker posts
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          ctx.beginPath();
          ctx.moveTo(bl.x, bl.y);
          ctx.lineTo(tl.x, tl.y);
          ctx.lineTo(tr.x, tr.y);
          ctx.lineTo(br.x, br.y);
          ctx.stroke();

          // Net
          ctx.strokeStyle = 'rgba(255,255,255,0.15)';
          ctx.lineWidth = 1;
          const steps = 12;
          for (let i=0; i<=steps; i++) {
             const t = i/steps;
             const lx = bl.x + (br.x - bl.x) * t;
             const ly = bl.y + (tl.y - bl.y) * t; 
             const tx = tl.x + (tr.x - tl.x) * t;
             ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(tx, ly - (ly-tl.y)); ctx.stroke();

             const hy = bl.y + (tl.y - bl.y) * t;
             ctx.beginPath(); ctx.moveTo(bl.x, hy); ctx.lineTo(br.x, hy); ctx.stroke();
          }
      }

      // Draw GK
      const gkProj = project(gkPos.current, w, h);
      if (gkProj.visible) {
        ctx.save();
        ctx.translate(gkProj.x, gkProj.y - (1.0 * gkProj.scale * 100)); 

        const gkS = gkProj.scale * 100;
        const lean = -gkVelX.current * 15; 
        ctx.rotate(lean * Math.PI / 180);

        ctx.fillStyle = '#ef4444';
        ctx.fillRect(-0.4 * gkS, -0.6 * gkS, 0.8 * gkS, 1.2 * gkS);

        ctx.fillStyle = '#fde047';
        ctx.beginPath(); ctx.arc(0, -0.9 * gkS, 0.25 * gkS, 0, Math.PI*2); ctx.fill();

        ctx.strokeStyle = '#ef4444';
        ctx.lineWidth = 0.2 * gkS;
        const armsUp = ballPos.current.y > 1.2 && gameState === GameState.KICKED;

        ctx.beginPath();
        ctx.moveTo(-0.4*gkS, -0.5*gkS);
        ctx.lineTo(-0.9*gkS, armsUp ? -1.1*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0.4*gkS, -0.5*gkS);
        ctx.lineTo(0.9*gkS, armsUp ? -1.1*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.restore();
      }

      // Draw Ball Shadow
      if (ballPos.current.y > 0) {
          const shadowProj = project({x: ballPos.current.x, y: 0.02, z: ballPos.current.z}, w, h);
          if (shadowProj.visible) {
              const heightFactor = Math.max(0, 1 - ballPos.current.y / 3); // Shadow fades as ball goes higher
              const sSize = BALL_RADIUS * shadowProj.scale * 100 * heightFactor; 
              ctx.fillStyle = `rgba(0,0,0,${0.4 * heightFactor})`;
              ctx.beginPath();
              ctx.ellipse(shadowProj.x, shadowProj.y, sSize, sSize * 0.3, 0, 0, Math.PI*2);
              ctx.fill();
          }
      }

      // Draw Ball
      const ballProj = project(ballPos.current, w, h);
      if (ballProj.visible) {
          const bRad = BALL_RADIUS * ballProj.scale * 100;
          ctx.translate(ballProj.x, ballProj.y);

          const rot = (ballPos.current.x + ballPos.current.z) * 5;
          ctx.rotate(rot);

          ctx.fillStyle = 'white';
          ctx.beginPath(); ctx.arc(0, 0, bRad, 0, Math.PI*2); ctx.fill();

          ctx.strokeStyle = '#1e293b';
          ctx.lineWidth = bRad * 0.15;
          ctx.beginPath(); ctx.moveTo(-bRad, 0); ctx.lineTo(bRad, 0); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, -bRad); ctx.lineTo(0, bRad); ctx.stroke();

          ctx.rotate(-rot);
          ctx.translate(-ballProj.x, -ballProj.y);
      }

      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
          ctx.beginPath();
          const start = dragPath.current[0];
          ctx.moveTo(start.x, start.y);
          for (let p of dragPath.current) ctx.lineTo(p.x, p.y);
          ctx.strokeStyle = 'rgba(52, 211, 153, 0.6)';
          ctx.lineWidth = 4;
          ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationFrameId);
  }, [gameState, getDifficultyParams, lastResult, project]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" width={window.innerWidth} height={window.innerHeight} />

      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-8 py-4 rounded-[40px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-3xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-10 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={20} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      <div className="absolute top-8 right-6 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-3 py-1.5 rounded-full border border-white/10 text-[10px] font-black text-white/60 tracking-wider">
           <Activity size={12} className="text-rose-500" />
           AI DIFF: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-32 h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
           <h2 className={`text-[6rem] md:text-[8rem] font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_30px_rgba(52,211,153,0.5)]' :
              lastResult === 'SAVE' ? 'text-rose-500' : 'text-zinc-600'
            }`}>
              {lastResult}!
            </h2>
             <div className="mt-4 bg-white/10 backdrop-blur-md text-white px-6 py-2 rounded-full text-xs tracking-widest uppercase border border-white/10 animate-pulse">
              Tap to Continue
            </div>
        </div>
      )}

      {gameState === GameState.IDLE && (
          <div className="absolute bottom-16 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 opacity-50 animate-bounce pointer-events-none">
            <div className="w-12 h-12 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-[10px] uppercase tracking-[0.3em]">Swipe Up to Kick</p>
          </div>
      )}

      <style>{`
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, Vec3, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- 3D WORLD CONSTANTS ---
// World units: Meters
const GOAL_DIST = 11.0; 
const GOAL_WIDTH = 10.0; // Widened for arcade fun (Standard 7.32)
const GOAL_HEIGHT = 3.0; // Taller (Standard 2.44)
const BALL_RADIUS = 0.22; // Size 5 ball approx
const GRAVITY = 0.012; 
const AIR_RESISTANCE = 0.985;
const FLOOR_BOUNCE = 0.6;
// Camera
const CAM_POS = { x: 0, y: 1.5, z: -4.0 }; // Moved slightly back/up for better view
const FOCAL_LENGTH = 750;

// --- DIFFICULTY TUNING ---
const BASE_GK_SPEED = 0.12; 
const MAX_GK_SPEED = 0.35;
const MAX_WIND_FORCE = 0.008;

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // 3D Physics State
  const ballPos = useRef<Vec3>({ x: 0, y: BALL_RADIUS, z: 0 });
  const ballVel = useRef<Vec3>({ x: 0, y: 0, z: 0 });
  const ballSpin = useRef<number>(0); 

  const gkPos = useRef<Vec3>({ x: 0, y: 0, z: GOAL_DIST - 0.5 });
  const gkVelX = useRef<number>(0);

  // Input State
  const dragStart = useRef<Vec2 | null>(null);
  const dragPath = useRef<Vec2[]>([]);
  const frameRef = useRef<number>(0);
  const windVector = useRef<Vec3>({ x: 0, y: 0, z: 0 });

  // 3D Projection Helper
  const project = useCallback((p: Vec3, width: number, height: number) => {
    const rx = p.x - CAM_POS.x;
    const ry = p.y - CAM_POS.y;
    const rz = p.z - CAM_POS.z;

    if (rz <= 0.1) return { x: -9999, y: -9999, scale: 0, visible: false };

    const scale = FOCAL_LENGTH / rz;
    const x = width / 2 + rx * scale;
    // Shift vanishing point to 40% height (simulate looking down slightly)
    const y = height * 0.4 - ry * scale; 

    return { x, y, scale: scale / 100, visible: true, zIndex: rz }; 
  }, []);

  const getDifficultyParams = useCallback(() => {
    const d = difficulty;
    const curve = d < 0.5 ? 2 * d * d : 1 - Math.pow(-2 * d + 2, 2) / 2;
    return {
      gkSpeed: BASE_GK_SPEED + curve * (MAX_GK_SPEED - BASE_GK_SPEED),
      windStrength: d * MAX_WIND_FORCE,
      predictionError: Math.max(0, 1.0 - d * 1.5)
    };
  }, [difficulty]);

  useEffect(() => {
    const interval = setInterval(() => {
        const angle = Date.now() / 2000;
        windVector.current = {
            x: Math.sin(angle) * getDifficultyParams().windStrength,
            y: 0,
            z: Math.cos(angle * 0.7) * getDifficultyParams().windStrength * 0.5
        };
    }, 100);
    return () => clearInterval(interval);
  }, [getDifficultyParams]);

  const resetBall = () => {
    ballPos.current = { x: 0, y: BALL_RADIUS, z: 0 };
    ballVel.current = { x: 0, y: 0, z: 0 };
    ballSpin.current = 0;
    gkPos.current = { x: 0, y: 0, z: GOAL_DIST - 0.5 };
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x, y };
    dragPath.current = [{ x, y }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current.push({ x, y });
    if (dragPath.current.length > 40) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 3) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    const dx = (end.x - start.x) / window.innerWidth;
    const dy = (end.y - start.y) / window.innerHeight; 

    const swipeDist = Math.sqrt(dx*dx + dy*dy);
    const swipeSpeed = swipeDist; 

    if (swipeDist < 0.05) {
        setGameState(GameState.IDLE);
        return;
    }

    let curveSum = 0;
    for(let i=1; i<dragPath.current.length-1; i++) {
        const p1 = dragPath.current[i-1];
        const p2 = dragPath.current[i];
        const p3 = dragPath.current[i+1];
        const v1 = { x: p2.x - p1.x, y: p2.y - p1.y };
        const v2 = { x: p3.x - p2.x, y: p3.y - p2.y };
        const cross = v1.x * v2.y - v1.y * v2.x;
        curveSum += cross;
    }
    const MAX_CURVE = 0.03;
    ballSpin.current = Math.max(-MAX_CURVE, Math.min(MAX_CURVE, curveSum * 0.00005));

    // Tuning power
    const powerZ = Math.min(0.9, Math.abs(dy) * 2.2 + swipeSpeed * 0.6); 
    const lift = Math.min(0.5, Math.abs(dy) * 1.3); 
    const side = dx * 1.5;

    ballVel.current = {
        x: side,
        y: lift * 0.5 + 0.1, 
        z: powerZ * 0.7 + 0.15 
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const update = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
          canvas.width = window.innerWidth;
          canvas.height = window.innerHeight;
      }

      const w = canvas.width;
      const h = canvas.height;
      const { gkSpeed, predictionError } = getDifficultyParams();

      ctx.clearRect(0, 0, w, h);

      // --- RENDER BACKGROUND ---
      // Horizon matched to vanishing point (0.4 * h)
      const horizonY = h * 0.4; 
      const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
      skyGrad.addColorStop(0, '#0f172a');
      skyGrad.addColorStop(1, '#1e293b');
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, w, horizonY);

      const fieldGrad = ctx.createLinearGradient(0, horizonY, 0, h);
      fieldGrad.addColorStop(0, '#064e3b');
      fieldGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = fieldGrad;
      ctx.fillRect(0, horizonY, w, h - horizonY);

      // Grid
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let z = 0; z <= 20; z += 2.5) {
          const p1 = project({ x: -12, y: 0, z }, w, h);
          const p2 = project({ x: 12, y: 0, z }, w, h);
          if (p1.visible && p2.visible) {
              ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }
      for (let x = -10; x <= 10; x += 2.5) {
          const p1 = project({ x, y: 0, z: -5 }, w, h);
          const p2 = project({ x, y: 0, z: 20 }, w, h);
          if (p1.visible && p2.visible) {
            ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }

      // --- PHYSICS UPDATE ---
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL');

      if (isMoving) {
        ballVel.current.x *= AIR_RESISTANCE;
        ballVel.current.y *= AIR_RESISTANCE;
        ballVel.current.z *= AIR_RESISTANCE;
        ballVel.current.y -= GRAVITY;
        ballVel.current.x += windVector.current.x + ballSpin.current;
        ballVel.current.z += windVector.current.z;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;
        ballPos.current.z += ballVel.current.z;

        if (ballPos.current.y < BALL_RADIUS) {
            ballPos.current.y = BALL_RADIUS;
            ballVel.current.y *= -FLOOR_BOUNCE;
            ballVel.current.x *= 0.8; 
            ballVel.current.z *= 0.8;
            if (Math.abs(ballVel.current.y) < 0.02) ballVel.current.y = 0;
        }

        if (gameState === GameState.KICKED) {
            const timeToGoal = (GOAL_DIST - ballPos.current.z) / ballVel.current.z;
            let targetX = gkPos.current.x;
            if (timeToGoal > 0 && timeToGoal < 30) {
                 const predictedX = ballPos.current.x + ballVel.current.x * timeToGoal;
                 const error = (Math.random() - 0.5) * predictionError * 2;
                 targetX = Math.max(-GOAL_WIDTH/2, Math.min(GOAL_WIDTH/2, predictedX + error));
            }
            const dist = targetX - gkPos.current.x;
            const move = Math.sign(dist) * Math.min(Math.abs(dist), gkSpeed);
            gkPos.current.x += move;
            gkVelX.current = move; 
        }

        if (gameState === GameState.KICKED && ballPos.current.z >= GOAL_DIST) {
            const inX = Math.abs(ballPos.current.x) < GOAL_WIDTH / 2 + BALL_RADIUS;
            const underBar = ballPos.current.y < GOAL_HEIGHT + BALL_RADIUS;

            const gkW = 1.0; 
            const gkH = 2.0; 
            const hitGK = 
                Math.abs(ballPos.current.x - gkPos.current.x) < gkW/2 + BALL_RADIUS &&
                ballPos.current.y < gkH + BALL_RADIUS;

            if (hitGK && inX && underBar) {
                setLastResult('SAVE');
                setGameState(GameState.RESULT);
                ballVel.current.z *= -0.3;
                ballVel.current.x += (Math.random() - 0.5) * 0.5;
                ballVel.current.y += 0.1;
                confetti({ particleCount: 50, spread: 40, origin: { y: 0.5 }, colors: ['#f43f5e'] });
                setDifficulty(d => Math.max(0.1, d - 0.05));
            } 
            else if (inX && underBar) {
                setLastResult('GOAL');
                setGameState(GameState.RESULT);
                ballVel.current.z *= 0.1; 
                confetti({ particleCount: 150, spread: 80, origin: { y: 0.4 }, colors: ['#10b981', '#fbbf24'] });
                setIsShaking(true); setTimeout(() => setIsShaking(false), 300);
                setMetrics(m => ({
                    ...m, score: m.score + 1, streak: m.streak + 1, bestStreak: Math.max(m.bestStreak, m.streak + 1)
                }));
                setDifficulty(d => Math.min(1.0, d + 0.08));
            } 
            else {
                setLastResult('MISS');
                setGameState(GameState.RESULT);
                setMetrics(m => ({ ...m, streak: 0 }));
                setDifficulty(d => Math.max(0.1, d - 0.03));
            }
        }

        if (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.z > GOAL_DIST + 2) {
             ballVel.current.z *= -0.5;
             ballPos.current.z = GOAL_DIST + 2;
        }
      } 
      else if (gameState === GameState.IDLE) {
         gkPos.current.x = Math.sin(Date.now() / 500) * 0.5;
         // Enforce ball position in IDLE to prevent ghosting or offset
         ballPos.current.x = 0;
         ballPos.current.y = BALL_RADIUS;
         ballPos.current.z = 0;
         ballVel.current = { x: 0, y: 0, z: 0 };
      }

      // --- RENDER SCENE ---
      const gD = GOAL_DIST;
      const gW = GOAL_WIDTH / 2;
      const gH = GOAL_HEIGHT;

      const bl = project({x: -gW, y: 0, z: gD}, w, h);
      const tl = project({x: -gW, y: gH, z: gD}, w, h);
      const tr = project({x: gW, y: gH, z: gD}, w, h);
      const br = project({x: gW, y: 0, z: gD}, w, h);

      // Draw Goal
      if (bl.visible && tr.visible) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = tl.scale * 15;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          ctx.beginPath();
          ctx.moveTo(bl.x, bl.y);
          ctx.lineTo(tl.x, tl.y);
          ctx.lineTo(tr.x, tr.y);
          ctx.lineTo(br.x, br.y);
          ctx.stroke();

          // Net
          ctx.strokeStyle = 'rgba(255,255,255,0.15)';
          ctx.lineWidth = 1;
          const steps = 14;
          for (let i=0; i<=steps; i++) {
             const t = i/steps;
             const lx = bl.x + (br.x - bl.x) * t;
             const ly = bl.y + (tl.y - bl.y) * t; 
             const tx = tl.x + (tr.x - tl.x) * t;
             ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(tx, ly - (ly-tl.y) * 0.8); ctx.stroke(); // 0.8 depth fake

             const hy = bl.y + (tl.y - bl.y) * t;
             ctx.beginPath(); ctx.moveTo(bl.x, hy); ctx.lineTo(br.x, hy); ctx.stroke();
          }
      }

      // Draw GK
      const gkProj = project(gkPos.current, w, h);
      if (gkProj.visible) {
        ctx.save();
        ctx.translate(gkProj.x, gkProj.y - (1.0 * gkProj.scale * 100)); 

        const gkS = gkProj.scale * 100;
        const lean = -gkVelX.current * 15; 
        ctx.rotate(lean * Math.PI / 180);

        ctx.fillStyle = '#ef4444';
        ctx.fillRect(-0.4 * gkS, -0.6 * gkS, 0.8 * gkS, 1.2 * gkS);

        ctx.fillStyle = '#fde047';
        ctx.beginPath(); ctx.arc(0, -0.9 * gkS, 0.25 * gkS, 0, Math.PI*2); ctx.fill();

        ctx.strokeStyle = '#ef4444';
        ctx.lineWidth = 0.2 * gkS;
        const armsUp = ballPos.current.y > 1.2 && gameState === GameState.KICKED;

        ctx.beginPath();
        ctx.moveTo(-0.4*gkS, -0.5*gkS);
        ctx.lineTo(-0.9*gkS, armsUp ? -1.1*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0.4*gkS, -0.5*gkS);
        ctx.lineTo(0.9*gkS, armsUp ? -1.1*gkS : -0.2*gkS);
        ctx.stroke();

        ctx.restore();
      }

      // Draw Ball Shadow
      if (ballPos.current.y > 0) {
          const shadowProj = project({x: ballPos.current.x, y: 0.02, z: ballPos.current.z}, w, h);
          if (shadowProj.visible) {
              const heightFactor = Math.max(0, 1 - ballPos.current.y / 3);
              const sSize = BALL_RADIUS * shadowProj.scale * 100 * heightFactor; 
              ctx.fillStyle = `rgba(0,0,0,${0.4 * heightFactor})`;
              ctx.beginPath();
              ctx.ellipse(shadowProj.x, shadowProj.y, sSize, sSize * 0.3, 0, 0, Math.PI*2);
              ctx.fill();
          }
      }

      // Draw Ball
      const ballProj = project(ballPos.current, w, h);
      if (ballProj.visible) {
          const bRad = BALL_RADIUS * ballProj.scale * 100;
          ctx.translate(ballProj.x, ballProj.y);

          const rot = (ballPos.current.x + ballPos.current.z) * 5;
          ctx.rotate(rot);

          ctx.fillStyle = 'white';
          ctx.beginPath(); ctx.arc(0, 0, bRad, 0, Math.PI*2); ctx.fill();

          ctx.strokeStyle = '#1e293b';
          ctx.lineWidth = bRad * 0.15;
          ctx.beginPath(); ctx.moveTo(-bRad, 0); ctx.lineTo(bRad, 0); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, -bRad); ctx.lineTo(0, bRad); ctx.stroke();

          ctx.rotate(-rot);
          ctx.translate(-ballProj.x, -ballProj.y);
      }

      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
          ctx.beginPath();
          const start = dragPath.current[0];
          ctx.moveTo(start.x, start.y);
          for (let p of dragPath.current) ctx.lineTo(p.x, p.y);
          ctx.strokeStyle = 'rgba(52, 211, 153, 0.6)';
          ctx.lineWidth = 4;
          ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationFrameId);
  }, [gameState, getDifficultyParams, lastResult, project]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" width={window.innerWidth} height={window.innerHeight} />

      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-8 py-4 rounded-[40px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-3xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-10 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={20} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      <div className="absolute top-8 right-6 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-3 py-1.5 rounded-full border border-white/10 text-[10px] font-black text-white/60 tracking-wider">
           <Activity size={12} className="text-rose-500" />
           AI DIFF: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-32 h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
           <h2 className={`text-[6rem] md:text-[8rem] font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_30px_rgba(52,211,153,0.5)]' :
              lastResult === 'SAVE' ? 'text-rose-500' : 'text-zinc-600'
            }`}>
              {lastResult}!
            </h2>
             <div className="mt-4 bg-white/10 backdrop-blur-md text-white px-6 py-2 rounded-full text-xs tracking-widest uppercase border border-white/10 animate-pulse">
              Tap to Continue
            </div>
        </div>
      )}

      {gameState === GameState.IDLE && (
          <div className="absolute bottom-16 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 opacity-50 animate-bounce pointer-events-none">
            <div className="w-12 h-12 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-[10px] uppercase tracking-[0.3em]">Swipe Up to Kick</p>
          </div>
      )}

      <style>{`
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, Vec3, GameMetrics } from './types';
import { RefreshCcw, Zap, Target, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- ASSETS ---
// Placeholder for the "Pig Hero" / GG Bond style character.
// You can replace this URL with the specific image URL you want to use.
const GK_IMG_URL = "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/499.png";

// --- 3D WORLD CONSTANTS ---
// World units: Meters
const GOAL_DIST = 11.0; 
const GOAL_WIDTH = 10.0; 
const GOAL_HEIGHT = 3.0; 
const BALL_RADIUS = 0.22; 
const GRAVITY = 0.012; 
const AIR_RESISTANCE = 0.985;
const FLOOR_BOUNCE = 0.6;
// Camera
const CAM_POS = { x: 0, y: 1.5, z: -4.0 }; 
const FOCAL_LENGTH = 750;

// --- DIFFICULTY TUNING ---
const BASE_GK_SPEED = 0.12; 
const MAX_GK_SPEED = 0.35;
const MAX_WIND_FORCE = 0.008;

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gkImageRef = useRef<HTMLImageElement>(new Image());

  // 3D Physics State
  const ballPos = useRef<Vec3>({ x: 0, y: BALL_RADIUS, z: 0 });
  const ballVel = useRef<Vec3>({ x: 0, y: 0, z: 0 });
  const ballSpin = useRef<number>(0); 

  const gkPos = useRef<Vec3>({ x: 0, y: 0, z: GOAL_DIST - 0.5 });
  const gkVelX = useRef<number>(0);

  // Input State
  const dragStart = useRef<Vec2 | null>(null);
  const dragPath = useRef<Vec2[]>([]);
  const frameRef = useRef<number>(0);
  const windVector = useRef<Vec3>({ x: 0, y: 0, z: 0 });

  // Load GK Image
  useEffect(() => {
    gkImageRef.current.src = GK_IMG_URL;
  }, []);

  // 3D Projection Helper
  const project = useCallback((p: Vec3, width: number, height: number) => {
    const rx = p.x - CAM_POS.x;
    const ry = p.y - CAM_POS.y;
    const rz = p.z - CAM_POS.z;

    if (rz <= 0.1) return { x: -9999, y: -9999, scale: 0, visible: false };

    const scale = FOCAL_LENGTH / rz;
    const x = width / 2 + rx * scale;
    const y = height * 0.4 - ry * scale; 

    return { x, y, scale: scale / 100, visible: true, zIndex: rz }; 
  }, []);

  const getDifficultyParams = useCallback(() => {
    const d = difficulty;
    const curve = d < 0.5 ? 2 * d * d : 1 - Math.pow(-2 * d + 2, 2) / 2;
    return {
      gkSpeed: BASE_GK_SPEED + curve * (MAX_GK_SPEED - BASE_GK_SPEED),
      windStrength: d * MAX_WIND_FORCE,
      predictionError: Math.max(0, 1.0 - d * 1.5)
    };
  }, [difficulty]);

  useEffect(() => {
    const interval = setInterval(() => {
        const angle = Date.now() / 2000;
        windVector.current = {
            x: Math.sin(angle) * getDifficultyParams().windStrength,
            y: 0,
            z: Math.cos(angle * 0.7) * getDifficultyParams().windStrength * 0.5
        };
    }, 100);
    return () => clearInterval(interval);
  }, [getDifficultyParams]);

  const resetBall = () => {
    ballPos.current = { x: 0, y: BALL_RADIUS, z: 0 };
    ballVel.current = { x: 0, y: 0, z: 0 };
    ballSpin.current = 0;
    gkPos.current = { x: 0, y: 0, z: GOAL_DIST - 0.5 };
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x, y };
    dragPath.current = [{ x, y }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current.push({ x, y });
    if (dragPath.current.length > 40) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 3) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    const dx = (end.x - start.x) / window.innerWidth;
    const dy = (end.y - start.y) / window.innerHeight; 

    const swipeDist = Math.sqrt(dx*dx + dy*dy);
    const swipeSpeed = swipeDist; 

    if (swipeDist < 0.05) {
        setGameState(GameState.IDLE);
        return;
    }

    let curveSum = 0;
    for(let i=1; i<dragPath.current.length-1; i++) {
        const p1 = dragPath.current[i-1];
        const p2 = dragPath.current[i];
        const p3 = dragPath.current[i+1];
        const v1 = { x: p2.x - p1.x, y: p2.y - p1.y };
        const v2 = { x: p3.x - p2.x, y: p3.y - p2.y };
        const cross = v1.x * v2.y - v1.y * v2.x;
        curveSum += cross;
    }
    const MAX_CURVE = 0.03;
    ballSpin.current = Math.max(-MAX_CURVE, Math.min(MAX_CURVE, curveSum * 0.00005));

    // Tuning power
    const powerZ = Math.min(0.9, Math.abs(dy) * 2.2 + swipeSpeed * 0.6); 
    const lift = Math.min(0.5, Math.abs(dy) * 1.3); 
    const side = dx * 1.5;

    ballVel.current = {
        x: side,
        y: lift * 0.5 + 0.1, 
        z: powerZ * 0.7 + 0.15 
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const update = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
          canvas.width = window.innerWidth;
          canvas.height = window.innerHeight;
      }

      const w = canvas.width;
      const h = canvas.height;
      const { gkSpeed, predictionError } = getDifficultyParams();

      ctx.clearRect(0, 0, w, h);

      // --- RENDER BACKGROUND ---
      const horizonY = h * 0.4; 
      const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
      skyGrad.addColorStop(0, '#0f172a');
      skyGrad.addColorStop(1, '#1e293b');
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, w, horizonY);

      const fieldGrad = ctx.createLinearGradient(0, horizonY, 0, h);
      fieldGrad.addColorStop(0, '#064e3b');
      fieldGrad.addColorStop(1, '#022c22');
      ctx.fillStyle = fieldGrad;
      ctx.fillRect(0, horizonY, w, h - horizonY);

      // Grid
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let z = 0; z <= 20; z += 2.5) {
          const p1 = project({ x: -12, y: 0, z }, w, h);
          const p2 = project({ x: 12, y: 0, z }, w, h);
          if (p1.visible && p2.visible) {
              ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }
      for (let x = -10; x <= 10; x += 2.5) {
          const p1 = project({ x, y: 0, z: -5 }, w, h);
          const p2 = project({ x, y: 0, z: 20 }, w, h);
          if (p1.visible && p2.visible) {
            ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
      }

      // --- PHYSICS UPDATE ---
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL');

      if (isMoving) {
        ballVel.current.x *= AIR_RESISTANCE;
        ballVel.current.y *= AIR_RESISTANCE;
        ballVel.current.z *= AIR_RESISTANCE;
        ballVel.current.y -= GRAVITY;
        ballVel.current.x += windVector.current.x + ballSpin.current;
        ballVel.current.z += windVector.current.z;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.y += ballVel.current.y;
        ballPos.current.z += ballVel.current.z;

        if (ballPos.current.y < BALL_RADIUS) {
            ballPos.current.y = BALL_RADIUS;
            ballVel.current.y *= -FLOOR_BOUNCE;
            ballVel.current.x *= 0.8; 
            ballVel.current.z *= 0.8;
            if (Math.abs(ballVel.current.y) < 0.02) ballVel.current.y = 0;
        }

        if (gameState === GameState.KICKED) {
            const timeToGoal = (GOAL_DIST - ballPos.current.z) / ballVel.current.z;
            let targetX = gkPos.current.x;
            if (timeToGoal > 0 && timeToGoal < 30) {
                 const predictedX = ballPos.current.x + ballVel.current.x * timeToGoal;
                 const error = (Math.random() - 0.5) * predictionError * 2;
                 targetX = Math.max(-GOAL_WIDTH/2, Math.min(GOAL_WIDTH/2, predictedX + error));
            }
            const dist = targetX - gkPos.current.x;
            const move = Math.sign(dist) * Math.min(Math.abs(dist), gkSpeed);
            gkPos.current.x += move;
            gkVelX.current = move; 
        }

        if (gameState === GameState.KICKED && ballPos.current.z >= GOAL_DIST) {
            const inX = Math.abs(ballPos.current.x) < GOAL_WIDTH / 2 + BALL_RADIUS;
            const underBar = ballPos.current.y < GOAL_HEIGHT + BALL_RADIUS;

            const gkW = 1.0; 
            const gkH = 1.8; 
            const hitGK = 
                Math.abs(ballPos.current.x - gkPos.current.x) < gkW/2 + BALL_RADIUS &&
                ballPos.current.y < gkH + BALL_RADIUS;

            if (hitGK && inX && underBar) {
                setLastResult('SAVE');
                setGameState(GameState.RESULT);
                ballVel.current.z *= -0.3;
                ballVel.current.x += (Math.random() - 0.5) * 0.5;
                ballVel.current.y += 0.1;
                confetti({ particleCount: 50, spread: 40, origin: { y: 0.5 }, colors: ['#f43f5e'] });
                setDifficulty(d => Math.max(0.1, d - 0.05));
            } 
            else if (inX && underBar) {
                setLastResult('GOAL');
                setGameState(GameState.RESULT);
                ballVel.current.z *= 0.1; 
                confetti({ particleCount: 150, spread: 80, origin: { y: 0.4 }, colors: ['#10b981', '#fbbf24'] });
                setIsShaking(true); setTimeout(() => setIsShaking(false), 300);
                setMetrics(m => ({
                    ...m, score: m.score + 1, streak: m.streak + 1, bestStreak: Math.max(m.bestStreak, m.streak + 1)
                }));
                setDifficulty(d => Math.min(1.0, d + 0.08));
            } 
            else {
                setLastResult('MISS');
                setGameState(GameState.RESULT);
                setMetrics(m => ({ ...m, streak: 0 }));
                setDifficulty(d => Math.max(0.1, d - 0.03));
            }
        }

        if (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.z > GOAL_DIST + 2) {
             ballVel.current.z *= -0.5;
             ballPos.current.z = GOAL_DIST + 2;
        }
      } 
      else if (gameState === GameState.IDLE) {
         gkPos.current.x = Math.sin(Date.now() / 500) * 0.5;
         ballPos.current.x = 0;
         ballPos.current.y = BALL_RADIUS;
         ballPos.current.z = 0;
         ballVel.current = { x: 0, y: 0, z: 0 };
      }

      // --- RENDER SCENE ---
      const gD = GOAL_DIST;
      const gW = GOAL_WIDTH / 2;
      const gH = GOAL_HEIGHT;

      const bl = project({x: -gW, y: 0, z: gD}, w, h);
      const tl = project({x: -gW, y: gH, z: gD}, w, h);
      const tr = project({x: gW, y: gH, z: gD}, w, h);
      const br = project({x: gW, y: 0, z: gD}, w, h);

      // Draw Goal
      if (bl.visible && tr.visible) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = tl.scale * 15;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          ctx.beginPath();
          ctx.moveTo(bl.x, bl.y);
          ctx.lineTo(tl.x, tl.y);
          ctx.lineTo(tr.x, tr.y);
          ctx.lineTo(br.x, br.y);
          ctx.stroke();

          // Net
          ctx.strokeStyle = 'rgba(255,255,255,0.15)';
          ctx.lineWidth = 1;
          const steps = 14;
          for (let i=0; i<=steps; i++) {
             const t = i/steps;
             const lx = bl.x + (br.x - bl.x) * t;
             const ly = bl.y + (tl.y - bl.y) * t; 
             const tx = tl.x + (tr.x - tl.x) * t;
             ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(tx, ly - (ly-tl.y) * 0.8); ctx.stroke();

             const hy = bl.y + (tl.y - bl.y) * t;
             ctx.beginPath(); ctx.moveTo(bl.x, hy); ctx.lineTo(br.x, hy); ctx.stroke();
          }
      }

      // Draw GK (Image)
      const gkProj = project(gkPos.current, w, h);
      if (gkProj.visible) {
        ctx.save();
        // Translate to FEET position (pivot point)
        ctx.translate(gkProj.x, gkProj.y); 

        const gkS = gkProj.scale * 100;
        // Lean into movement: if moving Right (+x), lean Right (+angle)
        // Standard angle direction in canvas: + is clockwise. 
        // Visual lean: top body goes to right -> clockwise.
        const lean = gkVelX.current * 15; 
        ctx.rotate(lean * Math.PI / 180);

        const gkImg = gkImageRef.current;
        const gkVisualWidth = 1.4 * gkS; // ~1.4m wide visual
        const gkVisualHeight = 1.8 * gkS; // ~1.8m tall visual

        if (gkImg && gkImg.complete && gkImg.naturalWidth > 0) {
            // Draw image upwards from feet (0,0) -> (-w/2, -h)
            ctx.drawImage(gkImg, -gkVisualWidth / 2, -gkVisualHeight, gkVisualWidth, gkVisualHeight);
        } else {
            // Fallback if image fails
            ctx.fillStyle = '#ef4444';
            ctx.fillRect(-gkVisualWidth/2, -gkVisualHeight, gkVisualWidth, gkVisualHeight);
        }

        ctx.restore();
      }

      // Draw Ball Shadow
      if (ballPos.current.y > 0) {
          const shadowProj = project({x: ballPos.current.x, y: 0.02, z: ballPos.current.z}, w, h);
          if (shadowProj.visible) {
              const heightFactor = Math.max(0, 1 - ballPos.current.y / 3);
              const sSize = BALL_RADIUS * shadowProj.scale * 100 * heightFactor; 
              ctx.fillStyle = `rgba(0,0,0,${0.4 * heightFactor})`;
              ctx.beginPath();
              ctx.ellipse(shadowProj.x, shadowProj.y, sSize, sSize * 0.3, 0, 0, Math.PI*2);
              ctx.fill();
          }
      }

      // Draw Ball
      const ballProj = project(ballPos.current, w, h);
      if (ballProj.visible) {
          const bRad = BALL_RADIUS * ballProj.scale * 100;
          ctx.translate(ballProj.x, ballProj.y);

          const rot = (ballPos.current.x + ballPos.current.z) * 5;
          ctx.rotate(rot);

          ctx.fillStyle = 'white';
          ctx.beginPath(); ctx.arc(0, 0, bRad, 0, Math.PI*2); ctx.fill();

          ctx.strokeStyle = '#1e293b';
          ctx.lineWidth = bRad * 0.15;
          ctx.beginPath(); ctx.moveTo(-bRad, 0); ctx.lineTo(bRad, 0); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, -bRad); ctx.lineTo(0, bRad); ctx.stroke();

          ctx.rotate(-rot);
          ctx.translate(-ballProj.x, -ballProj.y);
      }

      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
          ctx.beginPath();
          const start = dragPath.current[0];
          ctx.moveTo(start.x, start.y);
          for (let p of dragPath.current) ctx.lineTo(p.x, p.y);
          ctx.strokeStyle = 'rgba(52, 211, 153, 0.6)';
          ctx.lineWidth = 4;
          ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationFrameId);
  }, [gameState, getDifficultyParams, lastResult, project]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onMouseUp={handleInteractionEnd}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      onTouchEnd={handleInteractionEnd}
    >
      <canvas ref={canvasRef} className="w-full h-full block" width={window.innerWidth} height={window.innerHeight} />

      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/80 backdrop-blur-2xl px-8 py-4 rounded-[40px] border border-white/10 shadow-2xl pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-emerald-400 uppercase tracking-[0.2em] opacity-80">Goals</span>
          <span className="text-3xl font-black text-white">{metrics.score}</span>
        </div>
        <div className="w-px h-10 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[9px] font-black text-amber-400 uppercase tracking-[0.2em] opacity-80">Streak</span>
          <div className="flex items-center gap-2">
            <Zap size={20} className="fill-amber-400 text-amber-400 animate-pulse" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      <div className="absolute top-8 right-6 flex flex-col items-end gap-2 pointer-events-none z-10">
         <div className="flex items-center gap-2 bg-black/60 px-3 py-1.5 rounded-full border border-white/10 text-[10px] font-black text-white/60 tracking-wider">
           <Activity size={12} className="text-rose-500" />
           AI DIFF: {(difficulty * 100).toFixed(0)}%
         </div>
         <div className="w-32 h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 via-amber-400 to-rose-500 transition-all duration-1000" style={{ width: `${difficulty * 100}%` }} />
         </div>
      </div>

      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
           <h2 className={`text-[6rem] md:text-[8rem] font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-emerald-400 drop-shadow-[0_0_30px_rgba(52,211,153,0.5)]' :
              lastResult === 'SAVE' ? 'text-rose-500' : 'text-zinc-600'
            }`}>
              {lastResult}!
            </h2>
             <div className="mt-4 bg-white/10 backdrop-blur-md text-white px-6 py-2 rounded-full text-xs tracking-widest uppercase border border-white/10 animate-pulse">
              Tap to Continue
            </div>
        </div>
      )}

      {gameState === GameState.IDLE && (
          <div className="absolute bottom-16 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 opacity-50 animate-bounce pointer-events-none">
            <div className="w-12 h-12 border-2 border-white/30 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <p className="text-white font-black text-[10px] uppercase tracking-[0.3em]">Swipe Up to Kick</p>
          </div>
      )}

      <style>{`
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, Vec2, Vec3, GameMetrics } from './types';
import { Zap, Activity } from 'lucide-react';
import confetti from 'canvas-confetti';

// --- ASSETS ---
// Red Pig Hero (GG Bond style)
const GK_IMG_URL = "https://img95.699pic.com/photo/40156/9593.jpg_wh300.jpg"; 
// Using a fallback logic in code if this specific URL fails or to ensure a specific look, 
// but for now relying on a generic cartoon red pig or similar. 
// Since external hotlinks can be unstable, I will use a reliable placeholder of a "Red Pig" if needed, 
// but let's try to match the user's request with a specific red character sprite.
// A safe alternative if the above breaks is a generic red mascot.
// Let's use a different reliable URL for a "Red Cartoon Pig":
const GK_IMG_SOURCE = "https://img.ixintu.com/download/jpg/20200913/e0066d92576b55928646b9b207572767_512_512.jpg!con"; 
// Note: In a real production app, you should host the image yourself.

const SOCCER_BALL_URL = "https://upload.wikimedia.org/wikipedia/commons/d/d3/Soccerball.svg";

// --- 3D WORLD CONSTANTS ---
const GOAL_DIST = 11.0; 
const GOAL_WIDTH = 10.0; 
const GOAL_HEIGHT = 3.0; 
const BALL_RADIUS = 0.22; 
const GRAVITY = 0.012; 
const AIR_RESISTANCE = 0.985;
const FLOOR_BOUNCE = 0.6;
const GROUND_FRICTION = 0.92; // Friction when ball is rolling on grass
// Camera
const CAM_POS = { x: 0, y: 1.6, z: -4.5 }; 
const FOCAL_LENGTH = 800;

// --- DIFFICULTY TUNING ---
const BASE_GK_SPEED = 0.12; 
const MAX_GK_SPEED = 0.38;
const MAX_WIND_FORCE = 0.008;

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [difficulty, setDifficulty] = useState<number>(0.2); 
  const [metrics, setMetrics] = useState<GameMetrics>({
    score: 0,
    streak: 0,
    bestStreak: 0,
    attempts: 0
  });
  const [lastResult, setLastResult] = useState<'GOAL' | 'SAVE' | 'MISS' | null>(null);
  const [isShaking, setIsShaking] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gkImageRef = useRef<HTMLImageElement>(new Image());
  const ballImageRef = useRef<HTMLImageElement>(new Image());

  // 3D Physics State
  const ballPos = useRef<Vec3>({ x: 0, y: BALL_RADIUS, z: 0 });
  const ballVel = useRef<Vec3>({ x: 0, y: 0, z: 0 });
  const ballSpin = useRef<number>(0); 
  const ballRotation = useRef<number>(0); // Visual rotation angle

  const gkPos = useRef<Vec3>({ x: 0, y: 0, z: GOAL_DIST - 0.5 });
  const gkVelX = useRef<number>(0);

  // Input State
  const dragStart = useRef<Vec2 | null>(null);
  const dragPath = useRef<Vec2[]>([]);
  const windVector = useRef<Vec3>({ x: 0, y: 0, z: 0 });

  // Load Images
  useEffect(() => {
    // Attempt to load the user requested style image
    // Fallback or specific URL for "GG Bond" style red pig
    gkImageRef.current.src = GK_IMG_SOURCE; 
    ballImageRef.current.src = SOCCER_BALL_URL;
  }, []);

  // Global Input Handlers to prevent getting stuck
  useEffect(() => {
    const handleGlobalUp = () => {
      if (gameState === GameState.DRAGGING) {
         handleInteractionEnd();
      }
    };
    window.addEventListener('mouseup', handleGlobalUp);
    window.addEventListener('touchend', handleGlobalUp);
    return () => {
      window.removeEventListener('mouseup', handleGlobalUp);
      window.removeEventListener('touchend', handleGlobalUp);
    };
  }, [gameState]);

  // 3D Projection Helper
  const project = useCallback((p: Vec3, width: number, height: number) => {
    const rx = p.x - CAM_POS.x;
    const ry = p.y - CAM_POS.y;
    const rz = p.z - CAM_POS.z;

    if (rz <= 0.1) return { x: -9999, y: -9999, scale: 0, visible: false };

    const scale = FOCAL_LENGTH / rz;
    const x = width / 2 + rx * scale;
    const y = height * 0.35 - ry * scale; // Horizon at 35% height

    return { x, y, scale: scale / 100, visible: true, zIndex: rz }; 
  }, []);

  const getDifficultyParams = useCallback(() => {
    const d = difficulty;
    const curve = d < 0.5 ? 2 * d * d : 1 - Math.pow(-2 * d + 2, 2) / 2;
    return {
      gkSpeed: BASE_GK_SPEED + curve * (MAX_GK_SPEED - BASE_GK_SPEED),
      windStrength: d * MAX_WIND_FORCE,
      predictionError: Math.max(0, 1.0 - d * 1.5)
    };
  }, [difficulty]);

  useEffect(() => {
    const interval = setInterval(() => {
        const angle = Date.now() / 2000;
        windVector.current = {
            x: Math.sin(angle) * getDifficultyParams().windStrength,
            y: 0,
            z: Math.cos(angle * 0.7) * getDifficultyParams().windStrength * 0.5
        };
    }, 100);
    return () => clearInterval(interval);
  }, [getDifficultyParams]);

  const resetBall = () => {
    ballPos.current = { x: 0, y: BALL_RADIUS, z: 0 };
    ballVel.current = { x: 0, y: 0, z: 0 };
    ballSpin.current = 0;
    ballRotation.current = 0;
    gkPos.current = { x: 0, y: 0, z: GOAL_DIST - 0.5 };
    dragPath.current = [];
    setGameState(GameState.IDLE);
    setLastResult(null);
  };

  const handleInteractionStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState === GameState.RESULT) {
      resetBall();
      return;
    }
    if (gameState !== GameState.IDLE) return;

    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStart.current = { x, y };
    dragPath.current = [{ x, y }];
    setGameState(GameState.DRAGGING);
  };

  const handleInteractionMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== GameState.DRAGGING) return;
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragPath.current.push({ x, y });
    if (dragPath.current.length > 40) dragPath.current.shift();
  };

  const handleInteractionEnd = () => {
    if (gameState !== GameState.DRAGGING || dragPath.current.length < 3) {
      if (gameState === GameState.DRAGGING) setGameState(GameState.IDLE);
      return;
    }

    const start = dragPath.current[0];
    const end = dragPath.current[dragPath.current.length - 1];

    const dx = (end.x - start.x) / window.innerWidth;
    const dy = (end.y - start.y) / window.innerHeight; 

    const swipeDist = Math.sqrt(dx*dx + dy*dy);
    const swipeSpeed = swipeDist; 

    if (swipeDist < 0.05) {
        setGameState(GameState.IDLE);
        return;
    }

    let curveSum = 0;
    for(let i=1; i<dragPath.current.length-1; i++) {
        const p1 = dragPath.current[i-1];
        const p2 = dragPath.current[i];
        const p3 = dragPath.current[i+1];
        const v1 = { x: p2.x - p1.x, y: p2.y - p1.y };
        const v2 = { x: p3.x - p2.x, y: p3.y - p2.y };
        const cross = v1.x * v2.y - v1.y * v2.x;
        curveSum += cross;
    }
    const MAX_CURVE = 0.03;
    ballSpin.current = Math.max(-MAX_CURVE, Math.min(MAX_CURVE, curveSum * 0.00005));

    const powerZ = Math.min(0.9, Math.abs(dy) * 2.2 + swipeSpeed * 0.6); 
    const lift = Math.min(0.5, Math.abs(dy) * 1.3); 
    const side = dx * 1.5;

    ballVel.current = {
        x: side,
        y: lift * 0.5 + 0.1, 
        z: powerZ * 0.7 + 0.15 
    };

    setGameState(GameState.KICKED);
    setMetrics(prev => ({ ...prev, attempts: prev.attempts + 1 }));
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const update = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
          canvas.width = window.innerWidth;
          canvas.height = window.innerHeight;
      }

      const w = canvas.width;
      const h = canvas.height;
      const { gkSpeed, predictionError } = getDifficultyParams();

      ctx.clearRect(0, 0, w, h);

      // --- RENDER ATMOSPHERE ---
      const horizonY = h * 0.35; 

      // Sky
      const skyGrad = ctx.createLinearGradient(0, 0, 0, horizonY);
      skyGrad.addColorStop(0, '#0f172a');
      skyGrad.addColorStop(1, '#1e293b');
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, w, horizonY);

      // Stadium lights (Visual flair)
      ctx.fillStyle = 'rgba(255, 255, 255, 0.03)';
      ctx.beginPath();
      ctx.arc(w * 0.2, horizonY * 0.5, 100, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(w * 0.8, horizonY * 0.5, 100, 0, Math.PI * 2);
      ctx.fill();

      // Field (Striped Grass)
      const fieldGrad = ctx.createLinearGradient(0, horizonY, 0, h);
      fieldGrad.addColorStop(0, '#104e3b'); // Darker green at back
      fieldGrad.addColorStop(1, '#15803d'); // Lighter green at front
      ctx.fillStyle = fieldGrad;
      ctx.fillRect(0, horizonY, w, h - horizonY);

      // Draw Stripes
      ctx.save();
      for (let z = 0; z < 30; z += 3) {
          const p1 = project({ x: -20, y: 0, z }, w, h);
          const p2 = project({ x: 20, y: 0, z }, w, h);
          const p3 = project({ x: 20, y: 0, z + 1.5 }, w, h);
          const p4 = project({ x: -20, y: 0, z + 1.5 }, w, h);

          if (p1.visible) {
              ctx.fillStyle = 'rgba(255, 255, 255, 0.03)';
              ctx.beginPath();
              ctx.moveTo(p1.x, p1.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.lineTo(p3.x, p3.y);
              ctx.lineTo(p4.x, p4.y);
              ctx.fill();
          }
      }
      ctx.restore();

      // Penalty Area Line
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
      ctx.lineWidth = 2;
      const boxZ = GOAL_DIST - 16.5; // Approx penalty box dist
      const boxW = 20; 
      // Just drawing a simple line for the box edge to give scale
      const b1 = project({ x: -boxW, y: 0.05, z: 5 }, w, h);
      const b2 = project({ x: boxW, y: 0.05, z: 5 }, w, h);
      if (b1.visible && b2.visible) {
          ctx.beginPath();
          ctx.moveTo(b1.x, b1.y);
          ctx.lineTo(b2.x, b2.y);
          ctx.stroke();
      }


      // --- PHYSICS UPDATE ---
      const isMoving = gameState === GameState.KICKED || (gameState === GameState.RESULT && lastResult === 'GOAL');

      if (isMoving) {
        ballVel.current.x *= AIR_RESISTANCE;
        ballVel.current.z *= AIR_RESISTANCE;

        // Vertical physics
        ballVel.current.y -= GRAVITY;
        ballPos.current.y += ballVel.current.y;

        // Ground collision
        if (ballPos.current.y < BALL_RADIUS) {
            ballPos.current.y = BALL_RADIUS;
            ballVel.current.y *= -FLOOR_BOUNCE;

            // Apply ground friction
            ballVel.current.x *= GROUND_FRICTION;
            ballVel.current.z *= GROUND_FRICTION;

            // Stop if too slow
            if (Math.abs(ballVel.current.y) < 0.05) ballVel.current.y = 0;
            if (Math.abs(ballVel.current.z) < 0.05 && Math.abs(ballVel.current.x) < 0.05) {
                 ballVel.current.x = 0;
                 ballVel.current.z = 0;
            }
        }

        ballVel.current.x += windVector.current.x + ballSpin.current;
        ballVel.current.z += windVector.current.z;

        ballPos.current.x += ballVel.current.x;
        ballPos.current.z += ballVel.current.z;

        // Calculate rotation based on velocity (Visual only)
        const speed = Math.sqrt(ballVel.current.x**2 + ballVel.current.y**2 + ballVel.current.z**2);
        ballRotation.current += speed * 0.8;

        // GK AI
        if (gameState === GameState.KICKED) {
            const timeToGoal = (GOAL_DIST - ballPos.current.z) / ballVel.current.z;
            let targetX = gkPos.current.x;
            if (timeToGoal > 0 && timeToGoal < 30) {
                 const predictedX = ballPos.current.x + ballVel.current.x * timeToGoal;
                 const error = (Math.random() - 0.5) * predictionError * 2;
                 targetX = Math.max(-GOAL_WIDTH/2, Math.min(GOAL_WIDTH/2, predictedX + error));
            }
            const dist = targetX - gkPos.current.x;
            const move = Math.sign(dist) * Math.min(Math.abs(dist), gkSpeed);
            gkPos.current.x += move;
            gkVelX.current = move; 
        }

        // Collision & Game Rules
        if (gameState === GameState.KICKED && ballPos.current.z >= GOAL_DIST) {
            const inX = Math.abs(ballPos.current.x) < GOAL_WIDTH / 2 + BALL_RADIUS;
            const underBar = ballPos.current.y < GOAL_HEIGHT + BALL_RADIUS;

            const gkW = 1.0; 
            const gkH = 1.8; 
            const hitGK = 
                Math.abs(ballPos.current.x - gkPos.current.x) < gkW/2 + BALL_RADIUS &&
                ballPos.current.y < gkH + BALL_RADIUS;

            if (hitGK && inX && underBar) {
                setLastResult('SAVE');
                setGameState(GameState.RESULT);
                ballVel.current.z *= -0.3;
                ballVel.current.x += (Math.random() - 0.5) * 0.5;
                ballVel.current.y += 0.1;
                confetti({ particleCount: 50, spread: 40, origin: { y: 0.5 }, colors: ['#f43f5e'] });
                setDifficulty(d => Math.max(0.1, d - 0.05));
            } 
            else if (inX && underBar) {
                setLastResult('GOAL');
                setGameState(GameState.RESULT);
                ballVel.current.z *= 0.15; // Slow down but keep going into net
                confetti({ particleCount: 150, spread: 80, origin: { y: 0.4 }, colors: ['#10b981', '#fbbf24'] });
                setIsShaking(true); setTimeout(() => setIsShaking(false), 300);
                setMetrics(m => ({
                    ...m, score: m.score + 1, streak: m.streak + 1, bestStreak: Math.max(m.bestStreak, m.streak + 1)
                }));
                setDifficulty(d => Math.min(1.0, d + 0.08));
            } 
            else {
                setLastResult('MISS');
                setGameState(GameState.RESULT);
                setMetrics(m => ({ ...m, streak: 0 }));
                setDifficulty(d => Math.max(0.1, d - 0.03));
            }
        }

        // Net Bounce / Back wall
        if (gameState === GameState.RESULT && lastResult === 'GOAL' && ballPos.current.z > GOAL_DIST + 2.5) {
             ballVel.current.z *= -0.4;
             ballPos.current.z = GOAL_DIST + 2.5;
        }
      } 
      else if (gameState === GameState.IDLE) {
         gkPos.current.x = Math.sin(Date.now() / 600) * 0.4;
         ballPos.current.x = 0;
         ballPos.current.y = BALL_RADIUS;
         ballPos.current.z = 0;
         ballVel.current = { x: 0, y: 0, z: 0 };
         ballRotation.current = 0;
      }

      // --- RENDER SCENE OBJECTS ---
      const gD = GOAL_DIST;
      const gW = GOAL_WIDTH / 2;
      const gH = GOAL_HEIGHT;

      const bl = project({x: -gW, y: 0, z: gD}, w, h);
      const tl = project({x: -gW, y: gH, z: gD}, w, h);
      const tr = project({x: gW, y: gH, z: gD}, w, h);
      const br = project({x: gW, y: 0, z: gD}, w, h);

      // --- BETTER NET RENDER ---
      if (bl.visible && tr.visible) {
          const depth = 2.0;
          const bld = project({x: -gW, y: 0, z: gD + depth}, w, h);
          const tld = project({x: -gW, y: gH, z: gD + depth * 0.4}, w, h); // Tapered top
          const trd = project({x: gW, y: gH, z: gD + depth * 0.4}, w, h);
          const brd = project({x: gW, y: 0, z: gD + depth}, w, h);

          // Draw Netting (Grid)
          ctx.strokeStyle = 'rgba(230, 230, 230, 0.15)';
          ctx.lineWidth = 1;

          // Back Net
          const hLines = 8;
          const vLines = 15;

          ctx.beginPath();
          // Horizontal lines (Back)
          for(let i=0; i<=hLines; i++) {
              const t = i/hLines;
              const ly = bld.y + (tld.y - bld.y) * t;
              const ry = brd.y + (trd.y - brd.y) * t;
              ctx.moveTo(bld.x + (brd.x - bld.x) * 0, ly);
              ctx.lineTo(brd.x, ry);
          }
          // Vertical lines (Back)
          for(let i=0; i<=vLines; i++) {
              const t = i/vLines;
              const tx = tld.x + (trd.x - tld.x) * t;
              const bx = bld.x + (brd.x - bld.x) * t;
              ctx.moveTo(bx, bld.y);
              ctx.lineTo(tx, tld.y);
          }
          ctx.stroke();

          // Side Nets
          ctx.beginPath();
          // Left
          ctx.moveTo(bl.x, bl.y); ctx.lineTo(bld.x, bld.y); ctx.lineTo(tld.x, tld.y); ctx.lineTo(tl.x, tl.y);
          // Right
          ctx.moveTo(br.x, br.y); ctx.lineTo(brd.x, brd.y); ctx.lineTo(trd.x, trd.y); ctx.lineTo(tr.x, tr.y);
          ctx.stroke();

          // Goal Posts (Draw last to cover net ends)
          ctx.strokeStyle = '#e2e8f0'; // Slate-200
          ctx.lineWidth = tl.scale * 12;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          ctx.beginPath();
          ctx.moveTo(bl.x, bl.y);
          ctx.lineTo(tl.x, tl.y);
          ctx.lineTo(tr.x, tr.y);
          ctx.lineTo(br.x, br.y);
          ctx.stroke();
      }

      // --- GK RENDER (PIG HERO) ---
      const gkProj = project(gkPos.current, w, h);
      if (gkProj.visible) {
        ctx.save();
        ctx.translate(gkProj.x, gkProj.y); 

        const gkS = gkProj.scale * 100;
        const lean = gkVelX.current * 20; 
        ctx.rotate(lean * Math.PI / 180);

        const gkImg = gkImageRef.current;
        // Make GK slightly larger/toonier
        const gkVisualWidth = 1.6 * gkS; 
        const gkVisualHeight = 1.8 * gkS; 

        if (gkImg && gkImg.complete && gkImg.naturalWidth > 0) {
            ctx.drawImage(gkImg, -gkVisualWidth / 2, -gkVisualHeight, gkVisualWidth, gkVisualHeight);
        } else {
            // Backup visual if image fails
            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.roundRect(-gkVisualWidth/2, -gkVisualHeight, gkVisualWidth, gkVisualHeight, 20);
            ctx.fill();
        }

        ctx.restore();
      }

      // --- BALL RENDER ---
      // Shadow
      if (ballPos.current.y > 0) {
          const shadowProj = project({x: ballPos.current.x, y: 0.02, z: ballPos.current.z}, w, h);
          if (shadowProj.visible) {
              const heightFactor = Math.max(0, 1 - ballPos.current.y / 2.5);
              const sSize = BALL_RADIUS * shadowProj.scale * 100 * (0.8 + 0.2 * heightFactor); 
              ctx.fillStyle = `rgba(0,0,0,${0.3 * heightFactor})`;
              ctx.beginPath();
              ctx.ellipse(shadowProj.x, shadowProj.y, sSize, sSize * 0.3, 0, 0, Math.PI*2);
              ctx.fill();
          }
      }

      // Ball
      const ballProj = project(ballPos.current, w, h);
      if (ballProj.visible) {
          const bRad = BALL_RADIUS * ballProj.scale * 100;
          ctx.save();
          ctx.translate(ballProj.x, ballProj.y);

          // Rotate ball texture
          ctx.rotate(ballRotation.current);

          const ballImg = ballImageRef.current;
          if (ballImg && ballImg.complete && ballImg.naturalWidth > 0) {
             ctx.drawImage(ballImg, -bRad, -bRad, bRad * 2, bRad * 2);
          } else {
              // Fallback procedural ball
              ctx.fillStyle = 'white';
              ctx.beginPath(); ctx.arc(0, 0, bRad, 0, Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#1e293b';
              ctx.lineWidth = bRad * 0.1;
              ctx.beginPath(); ctx.moveTo(-bRad, 0); ctx.lineTo(bRad, 0); ctx.stroke();
              ctx.beginPath(); ctx.moveTo(0, -bRad); ctx.lineTo(0, bRad); ctx.stroke();
          }

          ctx.restore();
      }

      if (gameState === GameState.DRAGGING && dragPath.current.length > 1) {
          ctx.beginPath();
          const start = dragPath.current[0];
          ctx.moveTo(start.x, start.y);
          for (let p of dragPath.current) ctx.lineTo(p.x, p.y);
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 6;
          ctx.lineCap = 'round';
          ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationFrameId);
  }, [gameState, getDifficultyParams, lastResult, project]);

  return (
    <div 
      className={`relative w-full h-screen select-none overflow-hidden bg-zinc-950 font-sans ${isShaking ? 'shake' : ''}`}
      onMouseDown={handleInteractionStart}
      onMouseMove={handleInteractionMove}
      onTouchStart={handleInteractionStart}
      onTouchMove={handleInteractionMove}
      // Note: onMouseUp/onTouchEnd handled globally in useEffect
    >
      <canvas ref={canvasRef} className="w-full h-full block" width={window.innerWidth} height={window.innerHeight} />

      <div className="absolute top-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-black/60 backdrop-blur-md px-8 py-3 rounded-full border border-white/10 shadow-lg pointer-events-none z-10">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest opacity-90">Goals</span>
          <span className="text-3xl font-black text-white leading-none">{metrics.score}</span>
        </div>
        <div className="w-px h-8 bg-white/20 mx-2" />
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-amber-400 uppercase tracking-widest opacity-90">Streak</span>
          <div className="flex items-center gap-1.5 leading-none">
            <Zap size={16} className="fill-amber-400 text-amber-400" />
            <span className="text-3xl font-black text-white">{metrics.streak}</span>
          </div>
        </div>
      </div>

      {lastResult && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-20">
           <h2 className={`text-[5rem] md:text-[7rem] font-black italic uppercase tracking-tighter ${
              lastResult === 'GOAL' ? 'text-transparent bg-clip-text bg-gradient-to-b from-emerald-300 to-emerald-600 drop-shadow-2xl' :
              lastResult === 'SAVE' ? 'text-rose-500 drop-shadow-xl' : 'text-zinc-500'
            }`}>
              {lastResult}!
            </h2>
             <div className="mt-8 bg-black/40 backdrop-blur text-white px-6 py-2 rounded-full text-xs tracking-widest uppercase border border-white/20 animate-pulse">
              Tap Screen
            </div>
        </div>
      )}

      {gameState === GameState.IDLE && (
          <div className="absolute bottom-[20%] left-1/2 -translate-x-1/2 flex flex-col items-center gap-3 opacity-60 animate-bounce pointer-events-none">
             <div className="w-10 h-10 border-2 border-white rounded-full flex items-center justify-center">
                 <div className="w-2 h-2 bg-white rounded-full" />
             </div>
             <p className="text-white font-bold text-xs uppercase tracking-widest text-shadow">Swipe Up</p>
          </div>
      )}

      <style>{`
        .shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake { 10%, 90% { transform: translate3d(-1px, 0, 0); } 20%, 80% { transform: translate3d(2px, 0, 0); } 30%, 50%, 70% { transform: translate3d(-4px, 0, 0); } 40%, 60% { transform: translate3d(4px, 0, 0); } }
        .text-shadow { text-shadow: 0 2px 4px rgba(0,0,0,0.5); }
      `}</style>
    </div>
  );
};

export default App;

